def _rational(self, val):
        """Convert the given value to a rational, if necessary."""

        I32 = 4294967296 # Maximum 32 bit unsigned int (i.e. 'I') value
        if isinstance(val, int):
             numer, denom = val, 1
        elif isinstance(val, fractions.Fraction):
            numer, denom = val.numerator, val.denominator
        elif hasattr(val, 'numer'):
            (numer, denom) = (int(val.numer()), int(val.denom()))
        else:
            param.main.param.warning("Casting type '%s' to Fraction.fraction"
                               % type(val).__name__)
            frac = fractions.Fraction(str(val))
            numer, denom = frac.numerator, frac.denominator
        return numer % I32, denom % I32

def _rational(self, val):
        """Convert the given value to a rational, if necessary."""
        if isinstance(val, Rational):
            return val
        elif isinstance(val, int):
            return Rational(val)
        elif isinstance(val, float):
            return Rational(val)
        elif isinstance(val, Decimal):
            return Rational(val)
        elif isinstance(val, Fraction):
            return Rational(val)
        elif isinstance(val, Rational):
            return val
        else:
            raise TypeError("Cannot convert %s to a Rational" % val)

def update(self,identity,params=None, headers=None):
        """Update a payment.

        Updates a payment object. This accepts only the metadata parameter.

        Args:
              identity (string): Unique identifier, beginning with "PM".
              params (dict, optional): Request body.

        Returns:
              ListResponse of Payment instances
        """
        path = self._sub_url_params('/payments/:identity', {

            'identity': identity,
          })

        if params is not None:
            params = {self._envelope_key(): params}

        response = self._perform_request('PUT', path, params, headers,
                                         retry_failures=True)
        return self._resource_for(response)

def disconnect(self, abandon_session=False):
        """ Disconnects from the Responsys soap service

        Calls the service logout method and destroys the client's session information. Returns
        True on success, False otherwise.
        """
        self.connected = False
        if (self.session and self.session.is_expired) or abandon_session:
            try:
                self.logout()
            except:
                log.warning(
                    'Logout call to responsys failed, session may have not been terminated',
                    exc_info=True
                )
            del self.session
        return True

