async def _send_command(self, command):
        """
        This is a private utility method.
        The method sends a non-sysex command to Firmata.

        :param command:  command data

        :returns: length of data sent
        """
        send_message = ""

        for i in command:
            send_message += chr(i)
        result = None
        for data in send_message:
            try:
                result = await self.write(data)
            except():
                if self.log_output:
                    logging.exception('cannot send command')
                else:
                    print('cannot send command')
        return result

def get(self, server):
        """
        Returns ServerConfig instance with configuration given server.

        :raises ServerConfigConflictError:
            if configuration directory contains configuration for same server
            multiple times

        :raises ServerConfigMissingUrlError: if URL is not specified in the configuration

        :raises ServerConfigNotFoundError: if configuration for given server is not found
        """
        server_config = self.config.get(server)
        try:
            while server_config is None:
                new_config = self._read_next_config()
                server_config = new_config.get(server)
                new_config.update(self.config)
                self.config = new_config
        except StopIteration:
            return _default_server_configuration(server)

        if CONFIG_URL_KEY_NAME not in server_config:
            message = "'%s' must be specified in configuration for '%s'" \
                % (CONFIG_URL_KEY_NAME, server)
            raise ServerConfigMissingUrlError(message)

        return ServerConfig(server_config)

def visit_classdef(self, node):
        """Class visitor."""
        if not node_is_subclass(node, 'django.forms.models.ModelForm', '.ModelForm'):
            # we only care about forms
            return

        meta = _get_child_meta(node)

        if not meta:
            return

        for child in meta.get_children():
            if not isinstance(child, Assign):
                continue

            if child.targets[0].name == 'exclude':
                self.add_message('W%s04' % BASE_ID, node=child)
                break

def visit_classdef(self, node):
        """Class visitor."""
        self.visit(node.body)

def _valid_ip6(ip_address):
    """
    Check if the IPv6 address is valid and routable
    Return either True or False
    """
    try:
        socket.inet_pton(socket.AF_INET6, ip_address)
    except socket.error:
        return False
    return True

def _noise(seq, c, size=33, total=1000):
    """Create mature sequences around start/end"""
    if c == 'start':
        return seq[:size] + ''.join([random.choice(seq) for _ in range(total)]) + seq[-size:]
    elif c == 'end':
        return seq[:size] + ''.join([random.choice(seq) for _ in range(total)]) + seq[-size:]
    else:
        return seq

def get_gtf_db(gtf, in_memory=False):
    """
    create a gffutils DB
    """
    db_file = gtf + '.db'
    if gtf.endswith('.gz'):
        db_file = gtf[:-3] + '.db'
    if file_exists(db_file):
        return gffutils.FeatureDB(db_file)
    db_file = ':memory:' if in_memory else db_file
    if in_memory or not file_exists(db_file):
        debug('GTF database does not exist, creating...')
        infer_extent = guess_infer_extent(gtf)
        db = gffutils.create_db(gtf, dbfn=db_file,
                                infer_gene_extent=infer_extent)
        return db
    else:
        return gffutils.FeatureDB(db_file)

def get_gtf_db(gtf, in_memory=False):
    """
