def create_consumer(user, password, config_file_path, process_message, *args, **kwargs):
    """Create a pulse consumer. Call listen() to start listening."""
    queue_config = _read_json_file(filepath=config_file_path)

    exchanges = map(lambda x: queue_config['sources'][x]['exchange'], queue_config['sources'].keys())
    topics = map(lambda x: queue_config['sources'][x]['topic'], queue_config['sources'].keys())

    for i in range(0, len(exchanges)):
        LOG.info('Listening to (%s, %s)' % (exchanges[i], topics[i]))

    pulse_args = {
        # If the queue exists and is durable it should match
        'durable': queue_config['durable'] in ('true', 'True'),
        'password': password,
        'topic': topics,
        'user': user
    }

    if queue_config.get('applabel') is not None:
        pulse_args['applabel'] = queue_config['applabel']

    return PulseReplayConsumer(
        # A list with the exchanges of each element under 'sources'
        exchanges=exchanges,
        callback=process_message,
        **pulse_args
    )
    return consumer

def _skw_matches_comparator(kw0, kw1):
    """Compare 2 single keywords objects.

    First by the number of their spans (ie. how many times they were found),
    if it is equal it compares them by lenghts of their labels.
    """
    def compare(a, b):
        return (a > b) - (a < b)

    list_comparison = compare(len(kw1[1][0]), len(kw0[1][0]))
    if list_comparison:
        return list_comparison

    if kw0[0].isComposite() and kw1[0].isComposite():
        component_avg0 = sum(kw0[1][1]) / len(kw0[1][1])
        component_avg1 = sum(kw1[1][1]) / len(kw1[1][1])
        component_comparison = compare(component_avg1, component_avg0)
        if component_comparison:
            return component_comparison

    return compare(len(str(kw1[0])), len(str(kw0[0])))

def swap_args(self, new_args, new_length=None):
        """
        This returns the same AST, with the arguments swapped out for new_args.
        """
        if new_length is None:
            new_length = len(new_args)
        assert len(new_args) == new_length
        new_args = [self.new_node(arg) for arg in new_args]
        return self.new_node(self.node, self.args[:new_length], new_args)

def run_restore(self, snapshot: Dict[Union[str, Key], Any]) -> 'BaseItemCollection':
        """
        Restores the state of a collection from a snapshot
        """
        try:

            for name, snap in snapshot.items():
                if isinstance(name, Key):
                    self._nested_items[name.group].run_restore(snap)
                else:
                    self._nested_items[name].run_restore(snap)
            return self

        except Exception as e:
            raise SnapshotError('Error while restoring snapshot: {}'.format(self._snapshot)) from e

def deleteAllActivationKeys(server):
    """
    Delete all activation keys from Spacewalk

    CLI Example:

    .. code-block:: bash

        salt-run spacewalk.deleteAllActivationKeys spacewalk01.domain.com
    """

    try:
        client, key = _get_session(server)
    except Exception as exc:
        err_msg = 'Exception raised when connecting to spacewalk server ({0}): {1}'.format(server, exc)
        log.error(err_msg)
        return {'Error': err_msg}

    activation_keys = client.activationkey.listActivationKeys(key)

    deleted_keys = []
    failed_keys = []

    for aKey in activation_keys:
        if client.activationkey.delete(key, aKey['key']) == 1:
            deleted_keys.append(aKey['key'])
        else:
            failed_keys.append(aKey['key'])

    ret = {'deleted': deleted_keys}
    if failed_keys:
        ret['failed'] = failed_keys
    return ret

def _build_type(type_, value, property_path=None):
    """ Builds the schema definition based on the given type for the given value.

    :param type_: The type of the value
    :param value: The value to build the schema definition for
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :return: The built schema definition
    :rtype: Dict[str, Any]
    """
    if type_ == 'array':
        return _build_array(value, property_path)
    elif type_ == 'object':
        return _build_object(value, property_path)
    elif type_ == 'string':
        return _build_string(value, property_path)
    elif type_ == 'number':
        return _build_number(value, property_path)
    elif type_ == 'integer':
        return _build_integer(value, property_path)
    elif type_ == 'boolean':
        return _build_boolean(value, property_path)
    elif type_ == 'null':
        return _build_null(value, property_path)
    else:
        raise ValueError('Unknown type: {}'.format(type_))

def __remove_dir(self, ftp, remote_path):
        """
        Helper function to perform delete operation on the remote server

        :param ftp: SFTP handle to perform delete operation(s)
        :param remote_path: Remote path to remove
        """
        if remote_path.endswith('/'):
            for f in ftp.listdir(remote_path):
                self.__remove_dir(ftp, remote_path + f)
            ftp.rmdir(remote_path)
        else:
            ftp.remove(remote_path)

def xml(self, attribs = None,elements = None, skipchildren = False):
        """Serialises the FoLiA element to XML, by returning an XML Element (in lxml.etree) for this element and all its children. For string output, consider the xmlstring() method instead."""
        E = ElementMaker(namespace=NSFOLIA,nsmap={None: NSFOLIA, 'xml' : "http://www.w3.org/XML/1998/namespace"})

        if not attribs: attribs = {}
        if not elements: elements = []

        if self.id:
            attribs['id'] = self.id
            try:
                w = self.doc[self.id]
                attribs['t'] = w.text()
            except KeyError:
                pass

        e  = makeelement(E, '{' + NSFOLIA + '}' + self.XMLTAG, **attribs)
        return e

def xml(self, attribs = None,elements = None, skipchildren = False):
        """Serialises the FoLiA element to XML, by returning an XML Element (in lxml.etree) for this element and all its children. For string output, consider the xmlstring() method instead."""
        if attribs is None:
            attribs = {}
        if elements is None:
            elements = []
        # create the element
        element = etree.Element(self.tag, attrib = attribs)
        # add the children
        for child in self.children:
            if not skipchildren or not isinstance(child, FoLiAElement):
                element.append(child.xml())
        # add the text
        if self.text:
            element.text = self.text
        # return the element
        return element

def monitor_resource_sync_state(resource, callback, exit_event=None):
    """Coroutine that monitors a KATCPResource's sync state.

    Calls callback(True/False) whenever the resource becomes synced or unsynced. Will
    always do an initial callback(False) call. Exits without calling callback() if
    exit_event is set
    """
    while True:
        if exit_event is not None and exit_event.is_set():
            return
        if resource.synced:
            callback(True)
        else:
            callback(False)
        yield from resource.wait_synced()

def _wait_for(self, callback, timeout=None):
        """
        Spins until callback() returns truthy.
        """
        start = time.time()
        while not callback():
            if timeout is not None and time.time() - start > timeout:
                raise TimeoutError("Timed out waiting for {}".format(callback))
            time.sleep(0.01)

def gen_otu_dict(nex_obj, nexson_version=None):
    """Takes a NexSON object and returns a dict of
    otu_id -> otu_obj
    """
    if nexson_version is None:
        nexson_version = detect_nexson_version(nex_obj)
    if _is_by_id_hbf(nexson_version):
        otus = nex_obj['nexml']['otusById']
        if len(otus) > 1:
            d = {}
            for v in otus.values():
                d.update(v['otuById'])
            return d
        else:
            return otus.values()[0]['otuById']
    o_dict = {}
    for ob in nex_obj.get('otus', []):
        for o in ob.get('otu', []):
            oid = o['@id']
            o_dict[oid] = o
    return o_dict

def gen_otu_dict(nex_obj, nexson_version=None):
    """Takes a NexSON object and returns a dict of
    otu_id -> otu_obj
    """
    otu_dict = {}
    for otu_id in nex_obj['data']['otus']:
        otu_dict[otu_id] = nex_obj['data']['otus'][otu_id]
    return otu_dict

