def result(self, timeout=None):
        """Returns the result of the call that the future represents.

        :param timeout: The number of seconds to wait for the result
            if the future has not been completed. None, the default,
            sets no limit.
        :returns: The result of the call that the future represents.
        :raises: TimeoutError: If the timeout is reached before the
            future ends execution.
        :raises: Exception: If the call raises the Exception.
        """
        with self.__condition:
            if self.__state == FINISHED:
                return self.__get__result()

            lock = get_lock()
            if lock is not None:
                lock.release()
            self.__condition.wait(timeout)
            if lock is not None:
                lock.acquire()

            if self.__state == FINISHED:
                return self.__get__result()
            else:
                raise TimeoutError('Future: %r' % self.__method)

def result(self, timeout=None):
        """Returns the result of the call that the future represents.

        :param timeout: The number of seconds to wait for the result
            if the future has not been completed. None, the default,
            sets no limit.
        :returns: The result of the call that the future represents.
        :raises: TimeoutError: If the timeout is reached before the
            future ends execution.
        :raises: Exception: If the call raises the Exception.
        """
        if timeout is None:
            return self._result
        else:
            return self._result.get(timeout=timeout)

def create_or_update(model, *, defaults=None, save=True, **kwargs):
    """
    Create or update a django model instance.

    :param model:
    :param defaults:
    :param kwargs:
    :return: object, created, updated

    """
    obj, created = model._default_manager.get_or_create(defaults=defaults, **kwargs)

    updated = False
    if not created:
        if defaults:
            for k, v in defaults.items():
                if getattr(obj, k) != v:
                    setattr(obj, k, v)
                    updated = True

        if updated and save:
            obj.save()

    return obj, created, updated

def create_or_update(model, *, defaults=None, save=True, **kwargs):
    """
    Create or update a django model instance.

    :param model:
    :param defaults:
    :param kwargs:
    :return: object, created, updated

    """
    defaults = defaults or {}
    instance, created = model.objects.get_or_create(
        defaults=defaults, **kwargs
    )
    if not created:
        for k, v in kwargs.items():
            setattr(instance, k, v)
    if save:
        instance.save()
    return instance, created

def get_readme():
    """Generate long description"""
    pandoc = None
    for path in os.environ["PATH"].split(os.pathsep):
        path = path.strip('"')
        pandoc = os.path.join(path, 'pandoc')
        if os.path.isfile(pandoc) and os.access(pandoc, os.X_OK):
            break
        else:
            pandoc = None
    try:
        if pandoc:
            cmd = [pandoc, '-t', 'rst', 'README.md']
            long_description = os.popen(' '.join(cmd)).read()
        else:
            raise ValueError
    except BaseException:
        long_description = open("README.md").read()
    return long_description

def get_readme():
    """Generate long description"""
    with open('README.md', 'r') as f:
        return f.read()

def list_():
    """
    List the RAID devices.

    CLI Example:

    .. code-block:: bash

        salt '*' raid.list
    """
    ret = {}
    for raid in __salt__["raid.list_"]():
        ret[raid] = {}
        for disk in __salt__["raid.list_disks"](raid):
            ret[raid][disk] = {}
            for partition in __salt__["raid.list_partitions"](raid, disk):
                ret[raid][disk][partition] = {}
                for volume in __salt__["raid.list_volumes"](raid, disk, partition):
                    ret[raid][disk][partition][volume] = {}
                    for level in __salt__["raid.list_levels"](raid, disk, partition, volume):
                        ret[raid][disk][partition][volume][level] = {}
                        for member in __salt__["raid.list_members"](raid, disk, partition, volume, level):
                            ret[raid][disk][partition][volume][level][member] = {}
                            for status in __salt__["raid.list_status"](raid, disk, partition, volume, level, member):
                                ret[raid][disk][partition][volume][level][member][status] = {}
                                for attribute in __salt__["raid.list_attributes"](
                                    raid, disk, partition, volume, level, member, status
                                ):
                                    ret[raid][disk][partition][volume][level][member][status][attribute] = {}
                                    for value in __salt__["raid.list_values"](
                                        raid, disk, partition, volume, level, member, status, attribute
                                    ):
                                        ret[raid][disk][partition][volume][level][member][status][attribute][value] = {}
    return ret

def write_params(path, *args, **dicts):
    """Write parameters to file, so that it's readable by read_params.

    Uses INI file format.
    """
    path = Path(path)
    if not path.parent.is_dir():
        path.parent.mkdir(parents=True)
    if len(args) == 1:
        d = args[0]
        with path.open('w') as f:
            for key in d:
                f.write(key + ' = ' + str(d[key]) + '\n')
    else:
        with path.open('w') as f:
            for k, d in dicts.items():
                f.write('[' + k + ']\n')
                for key, val in d.items():
                    f.write(key + ' = ' + str(val) + '\n')

def write_params(path, *args, **dicts):
    """Write parameters to file, so that it's readable by read_params.

    Uses INI file format.
    """
    with open(path, 'w') as f:
        for arg in args:
            f.write(str(arg) + '\n')
        for key, value in dicts.items():
            f.write(key + ' = ' + str(value) + '\n')

