def getVariants(self, referenceName, startPosition, endPosition,
                    callSetIds=[]):
        """
        Returns an iterator over the specified variants. The parameters
        correspond to the attributes of a GASearchVariantsRequest object.
        """
        if callSetIds is None:
            callSetIds = self._callSetIds
        else:
            for callSetId in callSetIds:
                if callSetId not in self._callSetIds:
                    raise exceptions.CallSetNotInVariantSetException(
                        callSetId, self.getId())
        for record in self.getPysamVariants(
                referenceName, startPosition, endPosition):
            yield self.convertVariant(record, callSetIds)

def validate(self):
        """ Validate filter condition (template method).
        """
        if self.condition is None:
            raise ValueError('Condition is not defined.')

        if not isinstance(self.condition, dict):
            raise ValueError('Condition must be a dict.')

        if not self.condition.get('type'):
            raise ValueError('Condition type is not defined.')

        if self.condition['type'] not in self.condition_types:
            raise ValueError('Condition type is not supported.')

        if self.condition['type'] == 'and':
            self.validate_and()
        elif self.condition['type'] == 'or':
            self.validate_or()
        elif self.condition['type'] == 'not':
            self.validate_not()
        elif self.condition['type'] == 'eq':
            self.validate_eq()
        elif self.condition['type'] == 'neq':
            self.validate_neq()
        elif self.condition['type'] == 'lt':
            self.validate_lt()
        elif self.condition['type'] == 'lte':
            self.validate_lte()
        elif self.condition['type'] == 'gt':
            self.validate_gt()
        elif self.condition['type'] == 'gte':
            self.validate_gte()
        elif self.condition['type'] == 'in':
            self.validate_in()
        elif self.condition['type'] == 'nin':
            self.validate_nin()
        elif self.condition['type'] == 'exists':
            self.validate_exists()
        elif self.condition['type'] == 'regex':
            self.validate_regex()
        elif self.condition['type'] == 'size':
            self.validate_size()
        elif self.condition['type'] == 'all':
            self.validate_all()
        elif self.condition['type'] == 'elemMatch':
            self.validate_elemMatch()
        elif self.condition['type'] == 'mod':
            self.validate_mod()
        elif self.condition['type'] == 'where':
            self.validate_where()
        elif self.condition['type'] == 'geoWithin':
            self.validate

def shutdown_mp(self, clean=True):
        """Shutdown all the multiprocessing.

        :param bool clean: Whether to shutdown things cleanly, or force a quick and dirty shutdown.

        """
        # The server runs on a worker thread, so we need to shut it down first.
        if hasattr(self, 'server'):
            # Shutdown the server quickly.
            try:
                # For some strange reason, this throws an OSError on windows.
                self.server.socket.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
            self.server.socket.close()
            self.server.shutdown()
        if hasattr(self, 'handler'):
            self.handler.workers.stop_workers(clean)

def shutdown_mp(self, clean=True):
        """Shutdown all the multiprocessing.

        :param bool clean: Whether to shutdown things cleanly, or force a quick and dirty shutdown.

        """
        if clean:
            for p in self.processes:
                p.terminate()
        else:
            for p in self.processes:
                p.kill()

def load_config_file(config_file_path, config_file):
    """
    Loads a config file, whether it is a yaml file or a .INI file.

    :param config_file_path: Path of the configuration file, used to infer the file format.
    :returns: Dictionary representation of the configuration file.
    """

    if config_file_path.lower().endswith(".yaml"):
        return yaml.load(config_file)

    if any(config_file_path.lower().endswith(extension) for extension in INI_FILE_EXTENSIONS):
        return load_config_from_ini_file(config_file)

    # At this point we have to guess the format of the configuration file.
    try:
        return yaml.load(config_file)
    except yaml.YAMLError:
        pass

    try:
        return load_config_from_ini_file(config_file)
    except:
        pass

    raise Exception("Could not load configuration file!")

def load_config_file(config_file_path, config_file):
    """
    Loads a config file, whether it is a yaml file or a .INI file.

    :param config_file_path: Path of the configuration file, used to infer the file format.
    :returns: Dictionary representation of the configuration file.
    """
    if config_file_path.endswith('.yaml') or config_file_path.endswith('.yml'):
        with open(config_file_path, 'r') as config_file:
            return yaml.load(config_file)
    elif config_file_path.endswith('.ini'):
        config = configparser.ConfigParser()
        config.read(config_file_path)
        return config
    else:
        raise ValueError('Unknown configuration file format.')

def get_unattached_volumes(self):
        """Build a list of all volumes missing tags and not ignored. Returns a `dict` keyed by the issue_id with the
        volume as the value

        Returns:
            :obj:`dict` of `str`: `EBSVolume`
        """
        volumes = {}
        ignored_tags = dbconfig.get('ignore_tags', self.ns)
        for volume in EBSVolume.get_all().values():
            issue_id = get_resource_id('evai', volume.id)

            if len(volume.attachments) == 0:
                if len(list(filter(set(ignored_tags).__contains__, [tag.key for tag in volume.tags]))):
                    continue

                volumes[issue_id] = volume

        return volumes

def get_unattached_volumes(self):
        """Build a list of all volumes missing tags and not ignored. Returns a `dict` keyed by the issue_id with the
        volume as the value

        Returns:
            :obj:`dict` of `str`: `EBSVolume`
        """
        unattached_volumes = {}
        for volume in self.volumes:
            if not volume.is_ignored():
                if not volume.has_tags():
                    unattached_volumes[volume.issue_id] = volume
        return unattached_volumes

