def GetVmodlType(name):
   """ Get type from vmodl name """

   # If the input is already a type, just return
   if isinstance(name, type):
      return name

   # Try to get type from vmodl type names table
   typ = vmodlTypes.get(name)
   if typ:
      return typ

   # Else get the type from the _wsdlTypeMap
   isArray = name.endswith("[]")
   if isArray:
      name = name[:-2]
   ns, wsdlName = _GetWsdlInfo(name)
   try:
      typ = GetWsdlType(ns, wsdlName)
   except KeyError:
      raise KeyError(name)
   if typ:
      return isArray and typ.Array or typ
   else:
      raise KeyError(name)

def GetVmodlType(name):
   """ Get type from vmodl name """
   return vim.get_type(name)

def fitness(self, width, height):
        """
        In guillotine algorithm case, returns the min of the fitness of all 
        free sections, for the given dimension, both normal and rotated
        (if rotation enabled.)
        """
        assert(width > 0 and height > 0)

        # Get best fitness section.
        section, rotated = self._select_fittest_section(width, height)
        if not section:
            return None

        # Return fitness of returned section, with correct dimmensions if the
        # the rectangle was rotated.
        if rotated:
            return self._section_fitness(section, height, width)
        else:
            return self._section_fitness(section, width, height)

def uploadFile(uploadfunc, fileindex, existing, uf, skip_broken=False):
    """Update a file object so that the location is a reference to the toil file
    store, writing it to the file store if necessary.

    """

    if uf["location"].startswith("toilfs:") or uf["location"].startswith("_:"):
        return
    if uf["location"] in fileindex:
        uf["location"] = fileindex[uf["location"]]
        return
    if not uf["location"] and uf["path"]:
        uf["location"] = schema_salad.ref_resolver.file_uri(uf["path"])
    if uf["location"].startswith("file://") and not os.path.isfile(uf["location"][7:]):
        if skip_broken:
            return
        else:
            raise cwltool.errors.WorkflowException(
                "File is missing: %s" % uf["location"])
    uf["location"] = write_file(
        uploadfunc, fileindex, existing, uf["location"])

def uploadFile(uploadfunc, fileindex, existing, uf, skip_broken=False):
    """Update a file object so that the location is a reference to the toil file
    store, writing it to the file store if necessary.

    """
    # If the file is already in the file store, we don't need to do anything.
    if existing:
        return

    # If the file is not in the file store, we need to upload it.
    if skip_broken:
        try:
            uploadfunc(fileindex)
        except Exception:
            logger.warning("Skipping broken file %s", fileindex)
            return
    else:
        uploadfunc(fileindex)

def _add_details(self, info):
        """Override the base behavior to add Nodes, VirtualIPs, etc."""
        for (key, val) in six.iteritems(info):
            if key == "nodes":
                val = [Node(parent=self, **nd) for nd in val]
            elif key == "sessionPersistence":
                val = val['persistenceType']
            elif key == "cluster":
                val = val['name']
            elif key == "virtualIps":
                key = "virtual_ips"
                val = [VirtualIP(parent=self, **vip) for vip in val]
            setattr(self, key, val)

