def _get_site(self):
        """Returns the mwclient.Site for accessing and editing the wiki pages.
        """
        import mwclient
        parts = self.server.settings.wiki.replace("http", "").replace("://", "").split("/")
        self.url = parts[0]
        if len(parts) > 1 and parts[1].strip() != "":
            self.relpath = '/' + '/'.join(parts[1:len(parts)])
            #The API expects us to have a trailing forward-slash.
            if self.relpath[-1] != "/":
                self.relpath += "/"
            if not self.testmode:
                self.site = mwclient.Site(self.url, path=self.relpath)
        else:
            if not self.testmode:
                self.site = mwclient.Site(self.url)

def move(name, entry_name, config=None):
    """
    Move an entry to the sshconfig.
    """
    storm_ = get_storm_instance(config)

    try:

        if '@' in name:
            raise ValueError('invalid value: "@" cannot be used in name.')

        storm_.clone_entry(name, entry_name, keep_original=False)

        print(
            get_formatted_message(
                '{0} moved in ssh config. you can '
                'connect it by typing "ssh {0}".'.format(
                    entry_name
                ),
            'success')
        )

    except ValueError as error:
        print(get_formatted_message(error, 'error'), file=sys.stderr)
        sys.exit(1)

def move(name, entry_name, config=None):
    """
    Move an entry to the sshconfig.
    """
    if config is None:
        config = Config()

    entry = config.get_entry(entry_name)
    if entry is None:
        raise ValueError("Entry not found: %s" % entry_name)

    if name in config.entries:
        raise ValueError("Entry already exists: %s" % name)

    config.entries[name] = entry
    config.save()

