def open(self, mode):
        """
        Open the FileSystem target.

        This method returns a file-like object which can either be read from or written to depending
        on the specified mode.

        :param mode: the mode `r` opens the FileSystemTarget in read-only mode, whereas `w` will
                     open the FileSystemTarget in write mode. Subclasses can implement
                     additional options.
        :type mode: str
        """
        if mode == 'w':
            return self.format.pipe_writer(AtomicFtpFile(self._fs, self.path))

        elif mode == 'r':
            temp_dir = os.path.join(tempfile.gettempdir(), 'luigi-contrib-ftp')
            self.__tmp_path = temp_dir + '/' + self.path.lstrip('/') + '-luigi-tmp-%09d' % random.randrange(0, 1e10)
            # download file to local
            self._fs.get(self.path, self.__tmp_path)

            return self.format.pipe_reader(
                FileWrapper(io.BufferedReader(io.FileIO(self.__tmp_path, 'r')))
            )
        else:
            raise Exception("mode must be 'r' or 'w' (got: %s)" % mode)

def open(self, mode):
        """
        Open the FileSystem target.

        This method returns a file-like object which can either be read from or written to depending
        on the specified mode.

        :param mode: the mode `r` opens the FileSystemTarget in read-only mode, whereas `w` will
                     open the FileSystemTarget in write mode. Subclasses can implement
                     additional options.
        :type mode: str
        """
        if mode == 'r':
            return self._open_read()
        elif mode == 'w':
            return self._open_write()
        else:
            raise ValueError('Unsupported mode: {}'.format(mode))

def alreadyHasEntry(oldClassString, og):
    """ Return true if there is already an owl:Class with the old id"""
    namespace = oldClassString.split(':')[0]
    if namespace == 'http':
        target = rdflib.URIRef(oldClassString)
        print('OLD CLASS ID IS A URL', oldClassString)
    else:
        try:
            og.add_known_namespaces(namespace)
            target = og.expand(oldClassString)
        except KeyError:
            print('MISSING NAMESPACE', namespace, oldClassString)
            return True  # we only want known namespaces
    return (target, rdf.type, owl.Class) in og.g

def alreadyHasEntry(oldClassString, og):
    """ Return true if there is already an owl:Class with the old id"""
    for entry in og.graph.subjects(RDF.type, OWL.Class):
        if oldClassString in str(entry):
            return True
    return False

def my_import(name, path=None):
    """Return imported module for the given name."""
    if path is None:
        path = name
    __import__(path)
    return sys.modules[path]

def _usage_overall(raw):
    """
    Parse usage/overall.
    """
    usage = {}
    for line in raw.split('\n'):
        if line.startswith('Usage'):
            usage['Usage'] = line[len('Usage'):].strip()
        elif line.startswith('Total'):
            usage['Total'] = line[len('Total'):].strip()
        elif line.startswith('Used'):
            usage['Used'] = line[len('Used'):].strip()
        elif line.startswith('Free'):
            usage['Free'] = line[len('Free'):].strip()
        elif line.startswith('Shared'):
            usage['Shared'] = line[len('Shared'):].strip()
        elif line.startswith('Buffers'):
            usage['Buffers'] = line[len('Buffers'):].strip()
        elif line.startswith('Cached'):
            usage['Cached'] = line[len('Cached'):].strip()
        elif line.startswith('SwapCached'):
            usage['SwapCached'] = line[len('SwapCached'):].strip()
        elif line.startswith('Active'):
            usage['Active'] = line[len('Active'):].strip()
        elif line.startswith('Inactive'):
            usage['Inactive'] = line[len('Inactive'):].strip()
        elif line.startswith('Active(anon)'):
            usage['Active(anon)'] = line[len('Active(anon)'):].strip()
        elif line.startswith('Inactive(anon)'):
            usage['Inactive(anon)'] = line[len('Inactive(anon)'):].strip()
        elif line.startswith('Active(file)'):
            usage['Active(file)'] = line[len('Active(file)'):].strip()
        elif line.startswith('Inactive(file)'):
            usage['Inactive(file)'] = line[len('Inactive(file)'):].strip()
        elif line.startswith('Unevictable'):
            usage['Unevictable'] = line[len('Unevictable'):].strip()
        elif line.startswith('Mlocked'):
            usage['Mlocked'] = line[len('Mlocked'):].strip

def to_string(self, hdr, other):
        """String representation with additional information"""
        result = "%s[%s,%s" % (
                hdr, self.get_type(self.type), self.get_clazz(self.clazz))
        if self.unique:
            result += "-unique,"
        else:
            result += ","
        result += self.name
        if other is not None:
            result += ",%s]" % (other)
        else:
            result += "]"
        return result

def to_string(self, hdr, other):
        """String representation with additional information"""
        return '{} {}'.format(hdr, other)

def _remove_debug_handlers(self):
        """Remove any handlers with an attribute of debug_only that is True and
        remove the references to said handlers from any loggers that are
        referencing them.

        """
        remove = list()
        for handler in self.config[self.HANDLERS]:
            if self.config[self.HANDLERS][handler].get('debug_only'):
                remove.append(handler)
        for handler in remove:
            del self.config[self.HANDLERS][handler]
            for logger in self.config[self.LOGGERS].keys():
                logger = self.config[self.LOGGERS][logger]
                if handler in logger[self.HANDLERS]:
                    logger[self.HANDLERS].remove(handler)
        self._remove_debug_only()

def _remove_debug_handlers(self):
        """Remove any handlers with an attribute of debug_only that is True and
        remove the references to said handlers from any loggers that are
        referencing them.

        """
        for handler in self.handlers:
            if getattr(handler, 'debug_only', False):
                self.removeHandler(handler)

def nexec(statement, globals=None, locals=None, **kwargs):
    """Execute *statement* using *globals* and *locals* dictionaries as
    *global* and *local* namespace.  *statement* is transformed using
    :class:`.NapiTransformer`."""

    try:
        import __builtin__ as builtins
    except ImportError:
        import builtins

    from ast import parse
    from napi.transformers import NapiTransformer
    from ast import fix_missing_locations as fml
    try:
        node = parse(statement, '<string>', 'exec')
    except ImportError:#KeyError:
        exec(statement)
    else:
        if globals is None:
            globals = builtins.globals()
        if locals is None:
            locals = {}
        trans = NapiTransformer(globals=globals, locals=locals, **kwargs)
        trans.visit(node)
        code = compile(fml(node), '<string>', 'exec')
        return builtins.eval(code, globals, locals)

def nexec(statement, globals=None, locals=None, **kwargs):
    """Execute *statement* using *globals* and *locals* dictionaries as
    *global* and *local* namespace.  *statement* is transformed using
    :class:`.NapiTransformer`."""
    return NapiTransformer(globals=globals, locals=locals, **kwargs).transform(statement)

def published(self, for_user=None):
        """
        Return only published entries for the current site.
        """
        if appsettings.FLUENT_BLOGS_FILTER_SITE_ID:
            qs = self.parent_site(settings.SITE_ID)
        else:
            qs = self

        if for_user is not None and for_user.is_staff:
            return qs

        return qs \
            .filter(status=self.model.PUBLISHED) \
            .filter(
                Q(publication_date__isnull=True) |
                Q(publication_date__lte=now())
            ).filter(
                Q(publication_end_date__isnull=True) |
                Q(publication_end_date__gte=now())
            )

def published(self, for_user=None):
        """
        Return only published entries for the current site.
        """
        if for_user is None:
            for_user = self.request.user
        return self.filter(
            models.Q(sites__in=[self.request.site]) |
            models.Q(sites__isnull=True)
        )

def _wait_for_output(self):
        """
        Check if output matches banner.

        .. warning::
            Waiting for I/O completion. It does not work on Windows. Sorry.
        """
        if self.is_windows:
            return
        if not self.is_alive():
            return
        while not self.is_alive():
            time.sleep(0.1)
        while not self.is_output_matched():
            time.sleep(0.1)

def redo(self):
        """ Redo the last undone action.

        This is only possible if no other actions have occurred since the
        last undo call.
        """
        if self.canredo():
            undoable = self._redos.pop()
            with self._pausereceiver():
                try:
                    undoable.do()
                except:
                    self.clear()
                    raise
                else:
                    self._undos.append(undoable)
            self.docallback()

def get_group(self, t, i):
        """Get group number."""

        try:
            value = []
            if t in _DIGIT and t != '0':
                value.append(t)
                t = next(i)
                if t in _DIGIT:
                    value.append(t)
                else:
                    i.rewind(1)
        except StopIteration:
            pass
        return ''.join(value) if value else None

def get_group(self, t, i):
        """Get group number."""
        return self.groups[i]

def set_detail_level(self, detail_levels):
        """
        Sets the detail levels from the input dictionary in detail_levels.
        """
        if detail_levels is None:
            return

        self.detail_levels = detail_levels
        if 'api' in detail_levels:
            self.api_detail_level = detail_levels['api']
        if 'http' in detail_levels:
            self.http_detail_level = detail_levels['http']
        if isinstance(self.api_detail_level, int):
            self.api_maxlen = self.api_detail_level
        if isinstance(self.http_detail_level, int):
            self.http_maxlen = self.http_detail_level

def set_detail_level(self, detail_levels):
        """
        Sets the detail levels from the input dictionary in detail_levels.
        """
        if detail_levels is None:
            return
        for detail_level in detail_levels:
            self.set_detail_level(detail_level, detail_levels[detail_level])

