def nn_setsockopt(socket, level, option, value):
    """set a socket option

    socket - socket number
    level - option level
    option - option
    value - a readable byte buffer (not a Unicode string) containing the value
    returns - 0 on success or < 0 on error

    """
    try:
        return _nn_setsockopt(socket, level, option, ctypes.addressof(value),
                              len(value))
    except (TypeError, AttributeError):
        buf_value = ctypes.create_string_buffer(value)
        return _nn_setsockopt(socket, level, option,
                              ctypes.addressof(buf_value), len(value))

def start(self):
        """Start the consumer.  This starts a listen loop on a zmq.PULL socket,
        calling ``self.handle`` on each incoming request and pushing the response
        on a zmq.PUSH socket back to the producer."""
        self.socket = self.context.socket(zmq.PULL)
        self.socket.bind(self.endpoint)
        self.push_socket = self.context.socket(zmq.PUSH)
        self.push_socket.connect(self.push_endpoint)
        self.logger.info("Starting consumer on %s", self.endpoint)
        self.logger.info("Connecting to producer on %s", self.push_endpoint)
        while True:
            try:
                self.handle(self.socket.recv_json())
            except zmq.ZMQError as e:
                if e.errno == zmq.ETERM:
                    break
                else:
                    raise

def pop(self, key: str, default: Any = DEFAULT) -> Any:
        """
        Performs the functionality associated with dict.pop(key), along with checking for
        returned dictionaries, replacing them with Param objects with an updated history.

        If ``key`` is not present in the dictionary, and no default was specified, we raise a
        ``ConfigurationError``, instead of the typical ``KeyError``.
        """
        if default is self.DEFAULT:
            try:
                value = self.params.pop(key)
            except KeyError:
                raise ConfigurationError("key \"{}\" is required at location \"{}\"".format(key, self.history))
        else:
            value = self.params.pop(key, default)
        if not isinstance(value, dict):
            logger.info(self.history + key + " = " + str(value))  # type: ignore
        return self._check_is_dict(key, value)

def pop(self, key: str, default: Any = DEFAULT) -> Any:
        """
        Performs the functionality associated with dict.pop(key), along with checking for
        returned dictionaries, replacing them with Param objects with an updated history.

        If ``key`` is not present in the dictionary, and no default was specified, we raise a
        ``ConfigurationError``, instead of the typical ``KeyError``.
        """
        if key not in self:
            if default is DEFAULT:
                raise ConfigurationError(f"Key {key} not found in {self}")
            else:
                return default

        value = super().pop(key)
        if isinstance(value, dict):
            value = Param(value, history=self.history + [key])
        return value

