def update(self, e=None, **f):
        """Override dict.update() to title-case keys."""

        # Handle e first
        if e is not None:
            if hasattr(e, 'keys'):
                for k in e:
                    self[k.title()] = e[k]
            else:
                for (k, v) in e:
                    self[k.title()] = v

        # Now handle f
        if len(f):
            for k in f:
                self[k.title()] = f[k]

def update(self, e=None, **f):
        """Override dict.update() to title-case keys."""
        for k in f:
            f[k.title()] = f[k]
            del f[k]
        super().update(**f)

def strain_in_plane(self, **kwargs):
        """
        Returns the in-plane strain assuming no lattice relaxation, which
        is positive for tensile strain and negative for compressive strain.
        """
        if self._strain_out_of_plane is not None:
            return ((self._strain_out_of_plane / -2.) *
                    (self.unstrained.c11(**kwargs) /
                     self.unstrained.c12(**kwargs)  )  )
        else:
            return 1 - self.unstrained.a(**kwargs) / self.substrate.a(**kwargs)

def strain_in_plane(self, **kwargs):
        """
        Returns the in-plane strain assuming no lattice relaxation, which
        is positive for tensile strain and negative for compressive strain.
        """
        return self.strain_in_plane_with_relaxation(**kwargs)

def get_fields(self):
        """
        This returns a dictionary containing the top most fields,
        ``dates``, ``fields`` and ``queries``.
        """
        field_mapping = OrderedDict()
        for field, data in self.instance.items():
            field_mapping.update(
                {field: self.facet_dict_field_class(
                    child=self.facet_list_field_class(child=self.facet_field_serializer_class(data)), required=False)}
            )

        if self.serialize_objects is True:
            field_mapping["objects"] = serializers.SerializerMethodField()

        return field_mapping

def get_fields(self):
