            'dates': self.dates,
            'fields': self.fields,
            'queries': self.queries,
        }

def read(self, data, offset=0):
        """ Read data structure and return (nested) named tuple(s). """
        if isinstance(data, Buffer):
            return data.read(self)

        try:
            args = list(self._struct.unpack_from(data, offset))
        except TypeError as error:
            # Working around struct.unpack_from issue #10212
            logger.debug("error: %s", error)
            args = list(self._struct.unpack_from(str(bytearray(data)), offset))
        args.reverse()
        return self.popValue(args)

def read(self, data, offset=0):
        """ Read data structure and return (nested) named tuple(s). """
        if self.size is None:
            raise ValueError("size must be specified")
        if offset + self.size > len(data):
            raise ValueError("data is too short")
        return self.struct.unpack_from(data, offset)

def _get_node(self, time_qualifier, timeperiod):
        """
        Method retrieves a tree node identified by time_qualifier and timeperiod
        In case intermittent or target nodes does not exist - method will request their creation
        :param time_qualifier: identifies the tree level
        :param timeperiod: identifies the target node timeperiod
        :return: requested node; type <AbstractNode>
        """
        if time_qualifier == 'intermittent':
            if not self.intermittent_node:
                self.intermittent_node = self._create_node(time_qualifier, timeperiod)
            return self.intermittent_node
        else:
            if not self.target_node:
                self.target_node = self._create_node(time_qualifier, timeperiod)
            return self.target_node

def _create_binary_trigger(trigger):
    """Create an 8-bit binary trigger from an InputTrigger, TrueTrigger, FalseTrigger."""

    ops = {
        0: ">",
        1: "<",
        2: ">=",
        3: "<=",
        4: "==",
        5: 'always'
    }

    op_codes = {y: x for x, y in ops.items()}
    source = 0

    if isinstance(trigger, TrueTrigger):
        op_code = op_codes['always']
    elif isinstance(trigger, FalseTrigger):
        raise ArgumentError("Cannot express a never trigger in binary descriptor", trigger=trigger)
    else:
        op_code = op_codes[trigger.comp_string]

        if trigger.use_count:
            source = 1

    return (op_code << 1) | source

def _create_binary_trigger(trigger):
    """Create an 8-bit binary trigger from an InputTrigger, TrueTrigger, FalseTrigger."""
    if isinstance(trigger, InputTrigger):
        return trigger.value
    elif isinstance(trigger, TrueTrigger):
        return

def param_set(self, param_name, _value=None, **kwargs):
        """
        Setting parameter. if _value, we inject it directly. if not, we use all extra kwargs
        :param topic_name: name of the topic
        :param _value: optional value
        :param kwargs: each extra kwarg will be put in the value if structure matches
        :return:
        """
        if _value is not None:
            self.params[param_name] = _value
        else:
            for k, v in kwargs.items():
                if k in self.params[param_name]:
                    self.params[param_name][k] = v

