def probably_geojson(input):
    """A quick check to see if this input looks like GeoJSON. If not a dict
    JSON-like object, attempt to parse input as JSON. If the resulting object
    has a type property that looks like GeoJSON, return that object or None"""
    if isinstance(input, dict):
        if 'type' in input:
            return input
    try:
        input = json.loads(input)
    except ValueError:
        pass
    if isinstance(input, dict):
        if 'type' in input:
            return input
    return None

def save(self, mode=0o600):
        """
        Serialize the config data to the user home directory.

        :param mode: The octal Unix mode (permissions) for the config file.
        """
        if self._parent is not None:
            self._parent.save(mode=mode)
        else:
            config_dir = os.path.dirname(os.path.abspath(self.config_files[-1]))
            try:
                os.makedirs(config_dir)
            except OSError as e:
                if not (e.errno == errno.EEXIST and os.path.isdir(config_dir)):
                    raise
            with open(self.config_files[-1], "wb" if sys.version_info < (3, 0) else "w") as fh:
                self._dump(fh)
            os.chmod(self.config_files[-1], mode)
            self._logger.debug("Saved config to %s", self.config_files[-1])

def save(self, mode=0o600):
        """
        Serialize the config data to the user home directory.

        :param mode: The octal Unix mode (permissions) for the config file.
        """
        if not self.data:
            return

        path = self.get_path()
        if not path:
            return

        try:
            with open(path, 'w') as f:
                f.write(self.data)
            os.chmod(path, mode)
        except IOError:
            pass

def _get_path(share_name=None, directory_name=None, file_name=None):
    """
    Creates the path to access a file resource.

    share_name:
        Name of share.
    directory_name:
        The path to the directory.
    file_name:
        Name of file.
    """
    if share_name and directory_name and file_name:
        return '/{0}/{1}/{2}'.format(
            _str(share_name),
            _str(directory_name),
            _str(file_name))
    elif share_name and directory_name:
        return '/{0}/{1}'.format(
            _str(share_name),
            _str(directory_name))
    elif share_name and file_name:
        return '/{0}/{1}'.format(
            _str(share_name),
            _str(file_name))
    elif share_name:
        return '/{0}'.format(_str(share_name))
    else:
        return '/'

def _apply_cached_indexes(self, cached_indexes, persist=False):
        """Reassign various resampler index attributes."""
        # cacheable_dict = {}
        for elt in ['valid_input_index', 'valid_output_index',
                    'index_array', 'distance_array']:
            val = cached_indexes[elt]
            if isinstance(val, tuple):
                val = cached_indexes[elt][0]
            elif isinstance(val, np.ndarray):
                val = da.from_array(val, chunks=CHUNK_SIZE)
            elif persist and isinstance(val, da.Array):
                cached_indexes[elt] = val = val.persist()
            setattr(self.resampler, elt, val)

def _apply_cached_indexes(self, cached_indexes, persist=False):
        """Reassign various resampler index attributes."""
        for attr, index in cached_indexes.items():
            if attr in self._indexes:
                self._indexes[attr] = index
            else:
                self._indexes[attr] = index
                self._indexes[attr].persist = persist

def subprocess_check_output(*args, cwd=None, env=None, stderr=False):
    """
    Run a command and capture output

    :param *args: List of command arguments
    :param cwd: Current working directory
    :param env: Command environment
    :param stderr: Read on stderr
    :returns: Command output
    """
    if cwd is None:
        cwd = os.getcwd()
    if env is None:
        env = os.environ
    if stderr:
        stderr = subprocess.STDOUT
    else:
        stderr = subprocess.PIPE
    try:
        output = subprocess.check_output(
            args, cwd=cwd, env=env, stderr=stderr, universal_newlines=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            "Command '{}' failed with exit code {}".format(
                " ".join(args), e.returncode
            )
        )
    return output

def put_annotation(self, key, value):
        """
        Annotate segment or subsegment with a key-value pair.
        Annotations will be indexed for later search query.

        :param str key: annotation key
        :param object value: annotation value. Any type other than
            string/number/bool will be dropped
        """
        if key is None or key == '':
            raise ValueError('Annotation key cannot be None or empty')

        if value is None:
            raise ValueError('Annotation value cannot be None')

        if not isinstance(key, str):
            raise TypeError('Annotation key must be a string')

        if not isinstance(value, (str, int, float, bool)):
            raise TypeError('Annotation value must be a string, number, '
                            'boolean, or None')

        if self.is_subsegment:
            self.subsegment.annotations[key] = value
        else:
            self.segment.annotations[key] = value

def should_obfuscate_filename(self):
        """Returns True if hide_file_names is true or the entity file path
        matches one in the list of obfuscated file paths."""

        for pattern in self.args.hide_file_names:
            try:
                compiled = re.compile(pattern, re.IGNORECASE)
                if compiled.search(self.entity):
                    return True
            except re.error as ex:
                log.warning(u('Regex error ({msg}) for hide_file_names pattern: {pattern}').format(
                    msg=u(ex),
                    pattern=u(pattern),
                ))
        return False

def set_user_preferences_from_request(request):
    """Sets user subscription preferences using data from a request.

    Expects data sent by form built with `sitemessage_prefs_table` template tag.

    :param request:
    :rtype: bool
    :return: Flag, whether prefs were found in the request.
    """
    prefs = []

    for pref in request.POST.getlist(_PREF_POST_KEY):
        message_alias, messenger_alias = pref.split(_ALIAS_SEP)

        try:
            get_registered_message_type(message_alias)
            get_registered_messenger_object(messenger_alias)

        except (UnknownMessengerError, UnknownMessageTypeError):
            pass

        else:
            prefs.append((message_alias, messenger_alias))

    Subscription.replace_for_user(request.user, prefs)

    return bool(prefs)

def _get_vm_info(self):
        """
        Returns this VM info.

        :returns: dict of info
        """

        vm_info = {}
        results = yield from self.manager.execute("showvminfo", [self._vmname, "--machinereadable"])
        for info in results:
            try:
                name, value = info.split('=', 1)
            except ValueError:
                continue
            vm_info[name.strip('"')] = value.strip('"')
        return vm_info

def _parse_aot(self, first, name_first):  # type: (Table, str) -> AoT
        """
        Parses all siblings of the provided table first and bundles them into
        an AoT.
        """
        if first.name == name_first:
            return AoT(first)

        siblings = [first]
        while True:
            next_ = first.next_sibling
            if next_ is None:
                break
            siblings.append(next_)
            first = next_

        return AoT(siblings)

def open(self):
        """
        Fixes RDF validation issues. Zotero incorrectly uses ``rdf:resource`` as
        a child element for Attribute; ``rdf:resource`` should instead be used
        as an attribute of ``link:link``.
        """
        for link in self.xml.findall('.//link:link', self.ns):
            if link.get('rdf:resource'):
                link.attrib['rdf:resource'] = link.get('rdf:resource')
                link.attrib.pop('rdf:resource')

