def parse_declaration_expressn_memberaccess(self, lhsAST, rhsAST, es):
        """
        Instead of "Class.variablename", use "Class.rv('variablename')".

        :param lhsAST:
        :param rhsAST:
        :param es:
        :return:
        """
        if isinstance(lhsAST, wdl_parser.Terminal):
            es = es + lhsAST.source_string
        elif isinstance(lhsAST, wdl_parser.Ast):
            raise NotImplementedError
        elif isinstance(lhsAST, wdl_parser.AstList):
            raise NotImplementedError

        es = es + '_'

        if isinstance(rhsAST, wdl_parser.Terminal):
            es = es + rhsAST.source_string
        elif isinstance(rhsAST, wdl_parser.Ast):
            raise NotImplementedError
        elif isinstance(rhsAST, wdl_parser.AstList):
            raise NotImplementedError

        return es

def parse_declaration_expressn_memberaccess(self, lhsAST, rhsAST, es):
        """
        Instead of "Class.variablename", use "Class.rv('variablename')".

        :param lhsAST:
        :param rhsAST:
        :param es:
        :return:
        """
        if not isinstance(rhsAST, AST.MemberAccess):
            return
        if not isinstance(rhsAST.target, AST.Identifier):
            return
        if not isinstance(rhsAST.member, AST.Identifier):
            return
        if not isinstance(lhsAST, AST.Identifier):
            return
        if not isinstance(lhsAST.name, str):
            return
        if not isinstance(rhsAST.member.name, str):
            return
        if not isinstance(rhsAST.target.name, str):
            return
        if lhsAST.name != rhsAST.target.name:
            return
        if rhsAST.member.name != 'rv':
            return
        es.append(
            ExpressionStatement(
                Expression(
                    MemberAccess(
                        MemberAccess(
                            Identifier(
                                lhsAST.name
                            ),
                            Identifier(
                                'rv'
                            )
                        ),
                        Identifier(
                            rhsAST.member.name
                        )
                    )
                )
            )
        )

async def remove(ssid: str = None, name: str = None) -> Tuple[bool, str]:
    """ Remove a network. Depending on what is known, specify either ssid
    (in which case this function will call ``connection_exists`` to get the
    nmcli connection name) or the nmcli connection name directly.

    Returns (True, msg) if the connection was deleted, (False, msg) otherwise.
    """
    if None is not ssid:
        name = await connection_exists(ssid)
    if None is not name:
        res, err = await _call(['connection', 'delete', name])
        if 'successfully deleted' in res:
            return True, res
        else:
            return False, err
    else:
        return False, 'No connection for ssid {}'.format(ssid)

def get_children_labels(self, treepos):
        """Given the treeposition of a node, return the labels of its children."""
        children_labels = []
        node = self.dgtree[treepos]
        for child in node:
            if is_leaf(child):
                # we can't call .label() on a leaf node
                children_labels.append(child)
            else:
                children_labels.append(child.label())
        return children_labels

def get_children_labels(self, treepos):
        """Given the treeposition of a node, return the labels of its children."""
        return [self.label(child) for child in self.children(treepos)]

def _get_pooling_layers(self, start_node_id, end_node_id):
        """Given two node IDs, return all the pooling layers between them."""
        layer_list = []
        node_list = [start_node_id]
        assert self._depth_first_search(end_node_id, layer_list, node_list)
        ret = []
        for layer_id in layer_list:
            layer = self.layer_list[layer_id]
            if is_layer(layer, "Pooling"):
                ret.append(layer)
            elif is_layer(layer, "Conv") and layer.stride != 1:
                ret.append(layer)
        return ret

def _get_pooling_layers(self, start_node_id, end_node_id):
        """Given two node IDs, return all the pooling layers between them."""
        pooling_layers = []
        for node_id in range(start_node_id, end_node_id):
            node = self.nodes[node_id]
            if node.type == "Pooling":
                pooling_layers.append(node)
        return pooling_layers

