def ensure_tty(file=sys.stdout):
    """ Ensure a file object is a tty. It must have an `isatty` method that
        returns True.
        TypeError is raised if the method doesn't exist, or returns False.
    """
    isatty = getattr(file, 'isatty', None)
    if isatty is None:
        raise TypeError(
            'Cannot detect tty, file has no `isatty` method: {}'.format(
                getattr(file, 'name', type(file).__name__)
            )
        )
    if not isatty():
        raise TypeError(
            'This will not work, file object is not a tty: {}'.format(
                getattr(file, 'name', type(file).__name__)
            )
        )
    return True

def ensure_tty(file=sys.stdout):
    """ Ensure a file object is a tty. It must have an `isatty` method that
        returns True.
        TypeError is raised if the method doesn't exist, or returns False.
    """
    if not hasattr(file, 'isatty'):
        raise TypeError("file object has no isatty method")
    if not file.isatty():
        raise TypeError("file object is not a tty")

def register_arguments(func, args=None):
    """add given arguments to local

    args is a list that may contains nested lists
    (i.e. def func(a, (b, c, d)): ...)
    """
    if args is None:
        args = func.args.args
        if func.args.vararg:
            func.set_local(func.args.vararg, func.args)
        if func.args.kwarg:
            func.set_local(func.args.kwarg, func.args)
    for arg in args:
        if isinstance(arg, nodes.Name):
            func.set_local(arg.name, arg)
        else:
            register_arguments(func, arg.elts)

def register_arguments(func, args=None):
    """add given arguments to local

    args is a list that may contains nested lists
    (i.e. def func(a, (b, c, d)): ...)
    """
    if args is None:
        args = []
    if isinstance(args, list):
        for arg in args:
            register_arguments(func, arg)
    else:
        func.arguments.append(args)

def index(self, key):
        """ Return the index of the given item.

        :param key:
        :return:
        """
        if isinstance(key, int):
            if 0 <= key < len(self.__keys):
                return key
            raise IndexError(key)
        elif isinstance(key, str):
            try:
                return self.__keys.index(key)
            except ValueError:
                raise KeyError(key)
        else:
            raise TypeError(key)

def saveSettings(self, groupName=None):
        """ Writes the registry items into the persistent settings store.
        """
        if groupName is None:
            groupName = self.groupName
        if groupName is None:
            raise ValueError("No group name specified")
        if self.settings is None:
            raise ValueError("No settings to save")
        if not self.settings.has_key(groupName):
            raise ValueError("No settings for group %s" % groupName)
        settings = self.settings[groupName]
        for key, value in settings.items():
            self.setSetting(key, value, groupName)

def _acl_exists(name=None, id=None, token=None, consul_url=None):
    """
       Check the acl exists by using the name or the ID,
       name is ignored if ID is specified,
       if only Name is used the ID associated with it is returned
    """

    ret = {'result': False, 'id': None}

    if id:
        info = __salt__['consul.acl_info'](id=id, token=token, consul_url=consul_url)
    elif name:
        info = __salt__['consul.acl_list'](token=token, consul_url=consul_url)
    else:
        return ret

    if info.get('data'):
        for acl in info['data']:
            if id and acl['ID'] == id:
                ret['result'] = True
                ret['id'] = id
            elif name and acl['Name'] == name:
                ret['result'] = True
                ret['id'] = acl['ID']

    return ret

def evaluate(self, x):
        """
        Performs the evaluation of the objective at x.
        """

        if self.n_procs == 1:
            f_evals, cost_evals = self._eval_func(x)
        else:
            try:
                f_evals, cost_evals = self._syncronous_batch_evaluation(x)
            except:
                if not hasattr(self, 'parallel_error'):
                    print('Error in parallel computation. Fall back to single process!')
                else:
                    self.parallel_error = True
                f_evals, cost_evals = self._eval_func(x)

        return f_evals, cost_evals

def is_base_and_derived(based, derived):
    """returns True, if there is "base and derived" relationship between
    classes, False otherwise"""
    assert isinstance(based, class_declaration.class_t)
    assert isinstance(derived, (class_declaration.class_t, tuple))

    if isinstance(derived, class_declaration.class_t):
        all_derived = ([derived])
    else:  # tuple
        all_derived = derived

    for derived_cls in all_derived:
        for base_desc in derived_cls.recursive_bases:
            if base_desc.related_class == based:
                return True
    return False

