def to_dictionary(self):
        """Serialize an object into dictionary form.  Useful if you have to
        serialize an array of objects into JSON.  Otherwise, if you call the
        :meth:`to_json` method on each object in the list and then try to
        dump the array, you end up with an array with one string."""

        j = {}
        for p in self.properties:
            try:
                v = getattr(self, p)
            except AttributeError:
                continue
            if v is not None:
                if p == 't':
                    j[p] = getattr(self, p).isoformat()
                else:
                    j[p] = getattr(self, p)

        return j

def normalize_list(self, text, cache=None):
        """
        Get a canonical list representation of text, with words
        separated and reduced to their base forms.

        TODO: use the cache.
        """
        if not text:
            return []

        if isinstance(text, list):
            return text

        if isinstance(text, str):
            text = [text]

        if not isinstance(text, list):
            raise TypeError("text must be a string or a list of strings")

        if not text:
            return []

        if cache is None:
            cache = {}

        normalized_text = []
        for word in text:
            if word in cache:
                normalized_text.append(cache[word])
            else:
                normalized_text.append(self.normalize_word(word))

        return normalized_text

