def _post_keywords(self, **kwargs):
        """Configure keyword arguments for Open311 POST requests."""
        if self.jurisdiction and 'jurisdiction_id' not in kwargs:
            kwargs['jurisdiction_id'] = self.jurisdiction
        if 'address' in kwargs:
            address = kwargs.pop('address')
            kwargs['address_string'] = address
        if 'name' in kwargs:
            first, last = kwargs.pop('name').split(' ')
            kwargs['first_name'] = first
            kwargs['last_name'] = last
        if 'api_key' not in kwargs:
            kwargs['api_key'] = self.api_key
        return kwargs

def _is_common_binary(self, inpath):
        """private method to compare file path mime type to common binary file types"""
        # make local variables for the available char numbers in the suffix types to be tested
        two_suffix = inpath[-3:]
        three_suffix = inpath[-4:]
        four_suffix = inpath[-5:]

        # test for inclusion in the instance variable common_binaries (defined in __init__)
        if two_suffix in self.common_binaries:
            return True
        elif three_suffix in self.common_binaries:
            return True
        elif four_suffix in self.common_binaries:
            return True
        else:
            return False

def _is_common_binary(self, inpath):
        """private method to compare file path mime type to common binary file types"""
        if inpath.endswith('.exe') or inpath.endswith('.dll') or inpath.endswith('.so') or inpath.endswith('.dylib'):
            return True
        return False

def validate_with_schema(self, collection=None, context=None):
        """ Validate each item in collection with our schema"""
        if self._schema is None or not collection:
            return

        result = []
        try:
            for index, item in enumerate(collection):
                item_result = self._schema.validate(
                    model=item,
                    context=context if self.use_context else None
                )
                result.append(item_result)
        except TypeError:
            pass

        return result

def validate_with_schema(self, collection=None, context=None):
        """ Validate each item in collection with our schema"""
        if not collection:
            collection = self.collection
        if not context:
            context = self.context
        for item in collection:
            self.validate_with_schema_item(item, context)

def get_process_hardware_breakpoints(self, dwProcessId):
        """
        @see: L{get_thread_hardware_breakpoints}

        @type  dwProcessId: int
        @param dwProcessId: Process global ID.

        @rtype:  list of tuple( int, L{HardwareBreakpoint} )
        @return: All hardware breakpoints for each thread in the given process
            as a list of tuples (tid, bp).
        """
        result = list()
        aProcess = self.system.get_process(dwProcessId)
        for dwThreadId in aProcess.iter_thread_ids():
            if dwThreadId in self.__hardwareBP:
                bplist = self.__hardwareBP[dwThreadId]
                for bp in bplist:
                    result.append( (dwThreadId, bp) )
        return result

def get_process_hardware_breakpoints(self, dwProcessId):
        """
        @see: L{get_thread_hardware_breakpoints}

        @type  dwProcessId: int
        @param dwProcessId: Process global ID.

        @rtype:  list of tuple( int, L{HardwareBreakpoint} )
        @return: All hardware breakpoints for each thread in the given process
            as a list of tuples (tid, bp).
        """
        return self._get_thread_hardware_breakpoints(dwProcessId)

def popone(self, key, default=_marker):
        """Remove specified key and return the corresponding value.

        If key is not found, d is returned if given, otherwise
        KeyError is raised.

        """
        identity = self._title(key)
        for i in range(len(self._impl._items)):
            if self._impl._items[i][0] == identity:
                value = self._impl._items[i][2]
                del self._impl._items[i]
                self._impl.incr_version()
                return value
        if default is _marker:
            raise KeyError(key)
        else:
            return default

def ls(url='http://localhost:8080/manager', timeout=180):
    """
    list all the deployed webapps

    url : http://localhost:8080/manager
        the URL of the server manager webapp
    timeout : 180
        timeout for HTTP request

    CLI Examples:

    .. code-block:: bash

        salt '*' tomcat.ls
        salt '*' tomcat.ls http://localhost:8080/manager
    """
    ret = {}
    try:
        response = requests.get(url, timeout=timeout)
        response.raise_for_status()
        if response.text:
            for line in response.text.splitlines():
                if line.startswith('<a href="'):
                    app = line.split('"')[1]
                    ret[app] = {}
    except requests.exceptions.HTTPError as err:
        ret['error'] = err
    return ret

def hook_alias(self, alias, model_obj=None):
        """
        Returns the alias function, if it exists and if it can be applied to this model.
        """
        if model_obj is None:
            model_obj = self
        if alias in self.aliases:
            if self.aliases[alias].can_apply_to(model_obj):
                return self.aliases[alias]
        return None

def _ipconfig_getnode():
    """Get the hardware address on Windows by running ipconfig.exe."""
    import os, re
    dirs = ['', r'c:\windows\system32', r'c:\winnt\system32']
    try:
        import ctypes
        buffer = ctypes.create_string_buffer(300)
        ctypes.windll.kernel32.GetSystemDirectoryA(buffer, 300)  # @UndefinedVariable
        dirs.insert(0, buffer.value.decode('mbcs'))
    except:
        pass
    for dir in dirs:
        try:
            pipe = os.popen(os.path.join(dir, 'ipconfig') + ' /all')
        except IOError:
            continue
        for line in pipe:
            value = line.split(':')[-1].strip().lower()
            if re.match('([0-9a-f][0-9a-f]-){5}[0-9a-f][0-9a-f]', value):
                return int(value.replace('-', ''), 16)

def _ipconfig_getnode():
    """Get the hardware address on Windows by running ipconfig.exe."""
    import subprocess
    import re
    try:
        ipconfig = subprocess.check_output(
            ['ipconfig', '/all'],
            stderr=subprocess.STDOUT)
    except OSError:
        raise RuntimeError('Could not run ipconfig.exe')
    mac = re.search(
        r'Physical Address.+?((?:[a-f0-9]{2}\:){5}[a-f0-9]{2})',
        ipconfig, re.IGNORECASE | re.DOTALL)
    if mac:
        return mac.group(1)
    else:
        raise RuntimeError('Could not find MAC address')

def _skip_to_nonblank(f, spacegroup, setting):
    """Read lines from f until a nonblank line not starting with a
    hash (#) is encountered and returns this and the next line."""
    while True:
        line = f.readline()
        if not line:
            raise RuntimeError("Unexpected EOF in spacegroup file")
        if line.startswith("#"):
            continue
        if line.strip():
            break
    return line, f.readline()

def get_groups(self, roles):
        """get the list of groups from role"""
        ret = {}
        for role in roles:
            if role not in self.flatten:
                raise MissingRole(role)
            for b in self.flatten[role]['backends_groups']:
                if b not in ret:
                    ret[b] = []
                ret[b] = ret[b] + self.flatten[role]['backends_groups'][b]
        return ret

def get_groups(self, roles):
        """get the list of groups from role"""
        groups = []
        for role in roles:
            if role.get('type') == 'group':
                groups.append(role.get('name'))
        return groups

def get(self, section, val):
        """Get a setting or the default

        `Returns` The current value of the setting `val` or the default, or `None` if not found

        `section` (mandatory) (string) the section name in the config E.g. `"agent"`

        `val` (mandatory) (string) the section name in the config E.g. `"host"`
        """
        val = val.lower()
        if section in self.__config:
            if val in self.__config[section]:
                # logger.debug('get config %s %s = %s', section, val, self.__config[section][val])
                return self.__config[section][val]
        if section in self.__defaults:
            if val in self.__defaults[section]:
                # logger.debug('get defaults %s %s = %s', section, val, self.__defaults[section][val])
                return self.__defaults[section][val]
        return None

def get(self, section, val):
        """Get a setting or the default

        `Returns` The current value of the setting `val` or the default, or `None` if not found

        `section` (mandatory) (string) the section name in the config E.g. `"agent"`

        `val` (mandatory) (string) the section name in the config E.g. `"host"`
        """
        try:
            return self.config.get(section, val)
        except (NoOptionError, NoSectionError):
            return None

def update_storage(kwargs=None, conn=None, call=None):
    """
    .. versionadded:: 2015.8.0

    Update a storage account's properties

    CLI Example:

    .. code-block:: bash

        salt-cloud -f update_storage my-azure name=my_storage label=my_storage
    """
    if call != 'function':
        raise SaltCloudSystemExit(
            'The show_storage function must be called with -f or --function.'
        )

    if not conn:
        conn = get_conn()

    if kwargs is None:
        kwargs = {}

    if 'name' not in kwargs:
        raise SaltCloudSystemExit('A name must be specified as "name"')

    data = conn.update_storage_account(
        service_name=kwargs['name'],
        label=kwargs.get('label', None),
        description=kwargs.get('description', None),
        extended_properties=kwargs.get('extended_properties', None),
        geo_replication_enabled=kwargs.get('geo_replication_enabled', None),
        account_type=kwargs.get('account_type', 'Standard_GRS'),
    )
    return show_storage(kwargs={'name': kwargs['name']}, call='function')

def update_storage(kwargs=None, conn=None, call=None):
    """
    .. versionadded:: 2015.8.0

    Update a storage account's properties

    CLI Example:

    .. code-block:: bash

        salt-cloud -f update_storage my-azure name=my_storage label=my_storage
    """
    if call != "function":
        raise SaltCloudSystemExit(
            "The update_storage function must be called with -f or --function."
        )

    if not conn:
        conn = get_conn(**kwargs)

    if "name" not in kwargs:
        log.error("A storage account name is required.")
        return False

    storage_kwargs = {
        "label": kwargs.get("label", None),
        "description": kwargs.get("description", None),
        "affinity_group": kwargs.get("affinity_group", None),
        "location": kwargs.get("location", None),
    }

    try:
        conn.update_storage_account(kwargs["name"], **storage_kwargs)
    except WindowsAzureMissingResourceError as exc:
        log.error(
            "Failed to update storage account {0}: {1}".format(
                kwargs["name"], exc.message
            )
        )
        return False

    return True

def get_nowait(self) -> _T:
        """Remove and return an item from the queue without blocking.

        Return an item if one is immediately available, else raise
        `QueueEmpty`.
        """
        self._consume_expired()
        if self._putters:
            assert self.full(), "queue not full, why are putters waiting?"
            item, putter = self._putters.popleft()
            self.__put_internal(item)
            future_set_result_unless_cancelled(putter, None)
            return self._get()
        elif self.qsize():
            return self._get()
        else:
            raise QueueEmpty

def get_nowait(self) -> _T:
        """Remove and return an item from the queue without blocking.

        Return an item if one is immediately available, else raise
        `QueueEmpty`.
        """
        return self._get_impl(block=False)

def _diff_archives (archive1, archive2, verbosity=0, interactive=True):
    """Show differences between two archives.
    @return 0 if archives are the same, else 1
    @raises: PatoolError on errors
    """
    if util.is_same_file(archive1, archive2):
        return 0
    diff = util.find_program("diff")
    if not diff:
        msg = "The diff(1) program is required for showing archive differences, please install it."
        raise util.PatoolError(msg)
    tmpdir1 = util.tmpdir()
    try:
        path1 = _extract_archive(archive1, outdir=tmpdir1, verbosity=-1)
        tmpdir2 = util.tmpdir()
        try:
            path2 = _extract_archive(archive2, outdir=tmpdir2, verbosity=-1)
            return util.run_checked([diff, "-urN", path1, path2], verbosity=1, ret_ok=(0, 1))
        finally:
            shutil.rmtree(tmpdir2, onerror=rmtree_log_error)
    finally:
        shutil.rmtree(tmpdir1, onerror=rmtree_log_error)

