def list_tags(Name,
           region=None, key=None, keyid=None, profile=None):
    """
    List tags of a trail

    Returns:
        tags:
          - {...}
          - {...}

    CLI Example:

    .. code-block:: bash

        salt myminion boto_cloudtrail.list_tags my_trail

    """

    try:
        conn = _get_conn(region=region, key=key, keyid=keyid, profile=profile)
        rid = _get_trail_arn(Name,
                             region=region, key=key, keyid=keyid,
                             profile=profile)
        ret = conn.list_tags(ResourceIdList=[rid])
        tlist = ret.get('ResourceTagList', []).pop().get('TagsList')
        tagdict = {}
        for tag in tlist:
            tagdict[tag.get('Key')] = tag.get('Value')
        return {'tags': tagdict}
    except ClientError as e:
        return {'error': __utils__['boto3.get_error'](e)}

def list_tags(Name,
           region=None, key=None, keyid=None, profile=None):
    """
    List tags of a trail

    Returns:
        tags:
          - {...}
          - {...}

    CLI Example:

    .. code-block:: bash

        salt myminion boto_cloudtrail.list_tags my_trail

    """
    conn = _get_conn(region=region, key=key, keyid=keyid, profile=profile)
    try:
        tags = conn.list_tags(Name=Name)
    except (BotoServerError, BotoClientError) as e:
        return _handle_boto_error(e, 'list_tags', Name)

    return tags

def _set_catalog_view(self, session):
        """Sets the underlying catalog view to match current view"""
        if self._catalog_view == COMPARATIVE:
            try:
                session.use_comparative_catalog_view()
            except AttributeError:
                pass
        else:
            try:
                session.use_plenary_catalog_view()
            except AttributeError:
                pass

def _set_catalog_view(self, session):
        """Sets the underlying catalog view to match current view"""
        if self._catalog_view is None:
            self._catalog_view = self.view()
        else:
            self._catalog_view = self.view()
            self._catalog_view.update(self._catalog_view)

def getVMstats(self):
        """Return stats for Virtual Memory Subsystem.

        @return: Dictionary of stats.

        """
        info_dict = {}
        try:
            fp = open(vmstatFile, 'r')
            data = fp.read()
            fp.close()
        except:
            raise IOError('Failed reading stats from file: %s' % vmstatFile)
        for line in data.splitlines():
            cols = line.split()
            if len(cols) == 2:
                info_dict[cols[0]] = cols[1]
        return info_dict

def running(opts):
    """
    Return the running jobs on this minion
    """

    ret = []
    proc_dir = os.path.join(opts['cachedir'], 'proc')
    if not os.path.isdir(proc_dir):
        return ret
    for fn_ in os.listdir(proc_dir):
        path = os.path.join(proc_dir, fn_)
        try:
            data = _read_proc_file(path, opts)
            if data is not None:
                ret.append(data)
        except (IOError, OSError):
            # proc files may be removed at any time during this process by
            # the minion process that is executing the JID in question, so
            # we must ignore ENOENT during this process
            pass
    return ret

def running(opts):
    """
    Return the running jobs on this minion
    """
    ret = {}
    for job in __salt__["saltutil.running"](tgt=opts["id"]):
        ret[job] = __salt__["saltutil.running"](jid=job, tgt=opts["id"])
    return ret

def _sql_expand_insert(self, spec, key_prefix = '', col_prefix = ''):
        """ Expand a dict so it fits in a INSERT clause
        """
        if isinstance(spec, dict):
            return [self._sql_expand_insert(v, key_prefix + k + '.', col_prefix + k + '.') for k, v in spec.items()]
        elif isinstance(spec, list):
            return [self._sql_expand_insert(v, key_prefix, col_prefix) for v in spec]
        else:
            return [col_prefix + spec]

def convert(self, value, param, ctx):
        """Convert to URL scheme."""
        if not isinstance(value, tuple):
            parsed = urlparse.urlparse(value)
            if parsed.scheme not in ('telnet', 'ssh'):
                self.fail('invalid URL scheme (%s).  Only telnet and ssh URLs are '
                          'allowed' % parsed, param, ctx)
        return value

def convert(self, value, param, ctx):
        """Convert to URL scheme."""
        if value is None:
            return None
        if not isinstance(value, str):
            raise click.BadParameter('value must be a string')
        if value.startswith('http://'):
            return value
        if value.startswith('https://'):
            return value
        return 'http://' + value

def merge_extinfo(host, extinfo):
