        :param host: the host to edit
        :type host: alignak.objects.host.Host
        :param extinfo: the external info we get data from
        :type extinfo: alignak.objects.hostextinfo.HostExtInfo
        :return: None
        """
        if extinfo.host_id is not None:
            host.host_id = extinfo.host_id
        if extinfo.host_name is not None:
            host.host_name = extinfo.host_name
        if extinfo.host_ip is not None:
            host.host_ip = extinfo.host_ip
        if extinfo.host_mac is not None:
            host.host_mac = extinfo.host_mac
        if extinfo.host_os is not None:
            host.host_os = extinfo.host_os
        if extinfo.host_os_version is not None:
            host.host_os_version = extinfo.host_os_version
        if extinfo.host_os_arch is not None:
            host.host_os_arch = extinfo.host_os_arch
        if extinfo.host_os_kernel is not None:
            host.host_os_kernel = extinfo.host_os_kernel
        if extinfo.host_os_family is not None:
            host.host_os_family = extinfo.host_os_family
        if extinfo.host_os_type is not None:
            host.host_os_type = extinfo.host_os_type
        if extinfo.host_os_vendor is not None:
            host.host_os_vendor = extinfo.host_os_vendor
        if extinfo.host_os_device is not None:
            host.host_os_device = extinfo.host_os_device
        if extinfo.host_os_virtual is not None:
            host.host_os_virtual = extinfo.host_os_virtual
        if extinfo.host_os_virtual_type is not None:
            host.host_os_virtual_type = extinfo.host_os_virtual_type
        if extinfo.host_os_virtual_vendor is not None:
            host.host_os_virtual_vendor = extinfo.host_os_virtual_vendor
        if extinfo.host_os_virtual_version is not None:
            host.host_os_virtual_version = extinfo.host_os

def copy(self):
        """
        Returns a copy of the state.
        """
        return self.copy()

def check_token(self, token=None):
        """
        ADMIN ONLY. Returns True or False, depending on whether the current
        token is valid.
        """
        if token is None:
            token = self.token
        if token is None:
            return False
        try:
            self.get_token_info(token)
            return True
        except:
            return False

def setdocument(self, doc):
        """Associate a document with this element.

        Arguments:
            doc (:class:`Document`): A document

        Each element must be associated with a FoLiA document.
        """
        assert isinstance(doc, Document)

        if not self.doc:
            self.doc = doc
            if self.id:
                if self.id in doc:
                    raise DuplicateIDError(self.id)
                else:
                    self.doc.index[id] = self

        for e in self: #recursive for all children
            if isinstance(e,AbstractElement): e.setdocument(doc)

def TextToAttachmentStatus(self, Text):
        """Returns attachment status code.

        :Parameters:
          Text : unicode
            Text, one of 'UNKNOWN', 'SUCCESS', 'PENDING_AUTHORIZATION', 'REFUSED', 'NOT_AVAILABLE',
            'AVAILABLE'.

        :return: Attachment status.
        :rtype: `enums`.apiAttach*
        """
        if Text == 'UNKNOWN':
            return enums.apiAttachUnknown
        elif Text == 'SUCCESS':
            return enums.apiAttachSuccess
        elif Text == 'PENDING_AUTHORIZATION':
            return enums.apiAttachPendingAuthorization
        elif Text == 'REFUSED':
            return enums.apiAttachRefused
        elif Text == 'NOT_AVAILABLE':
            return enums.apiAttachNotAvailable
        elif Text == 'AVAILABLE':
            return enums.apiAttachAvailable
        else:
            raise ValueError('Unknown attachment status: %s' % Text)

def issues_notifications(user):
    """Notify user about open issues"""
    notifications = []

    # Only fetch required fields for notification serialization
    # Greatly improve performances and memory usage
    qs = issues_for(user).only('id', 'title', 'created', 'subject')

    # Do not dereference subject (so it's a DBRef)
    # Also improve performances and memory usage
    for issue in qs.no_dereference():
        notifications.append((issue.created, {
            'id': issue.id,
            'title': issue.title,
            'subject': {
                'id': issue.subject['_ref'].id,
                'type': issue.subject['_cls'].lower(),
            }
        }))

    return notifications

def issues_notifications(user):
    """Notify user about open issues"""
    issues = Issue.objects.filter(
        Q(assigned_to=user) | Q(created_by=user),
        status__in=['open', 'reopened'],
    )
    if issues.exists():
        return True
    return False

def get_extensions(extstr):
    """Return zero or greater Annotation Extensions, given a line of text."""
    # Extension examples:
    #   has_direct_input(UniProtKB:P37840),occurs_in(GO:0005576)
    #   part_of(UBERON:0006618),part_of(UBERON:0002302)
    #   occurs_in(CL:0000988)|occurs_in(CL:0001021)
    if not extstr:
        return None
    exts = []
    for ext_lst in extstr.split('|'):
        grp = []
        for ext in ext_lst.split(','):
            idx = ext.find('(')
            if idx != -1 and ext[-1] == ')':
                grp.append(AnnotationExtension(ext[:idx], ext[idx+1:-1]))
            else:
                # Ignore improperly formatted Extensions
                sys.stdout.write('BAD Extension({E})\n'.format(E=ext))
        exts.append(grp)
    return AnnotationExtensions(exts)

def get_extensions(extstr):
    """Return zero or greater Annotation Extensions, given a line of text."""
    if not extstr:
        return []
    exts = []
    for ext in extstr.split(','):
        exts.append(ext.strip())
    return exts

def best_for_flags(self, flags: Flags) -> List[TransItem]:
        """
        Given `flags`, find all items of this sentence that have an equal
        matching score and put them in a list.
        """
        items = []
        for item in self.items:
            if item.flags == flags:
                items.append(item)
        return items

def _load_referenced_schemes_from_list(the_list, val, a_scheme, a_property):
    """
    takes the referenced files and loads them
    returns the updated schema
    :param the_list:
    :param val:
    :param a_scheme:
    :param a_property:
    :return:
    """
    if isinstance(val, list):
        for item in val:
            if isinstance(item, dict):
                _load_referenced_schemes_from_dict(item, a_scheme, a_property)
            elif isinstance(item, str):
                _load_referenced_schemes_from_string(item, a_scheme, a_property)
    elif isinstance(val, dict):
        _load_referenced_schemes_from_dict(val, a_scheme, a_property)
    elif isinstance(val, str):
        _load_referenced_schemes_from_string(val, a_scheme, a_property)

def str_to_num(i, exact_match=True):
    """
    Attempts to convert a str to either an int or float
    """
    # TODO: Cleanup -- this is really ugly
    if not isinstance(i, str):
        return i
    try:
        if not exact_match:
            return int(i)
        elif str(int(i)) == i:
            return int(i)
        elif str(float(i)) == i:
            return float(i)
        else:
            pass
    except ValueError:
        pass
    return i

def str_to_num(i, exact_match=True):
    """
    Attempts to convert a str to either an int or float
    """
    try:
        return int(i)
    except ValueError:
        try:
            return float(i)
        except ValueError:
            if exact_match:
                raise ValueError("Could not convert string to int or float")
            return i

def tokenize_tags(tags_string):
    """
    This function is responsible to extract usable tags from a text.
    :param tags_string: a string of text
    :return: a string of comma separated tags
    """
    tags = []
    for tag in tags_string.split(','):
        tag = tag.strip()
        if tag:
            tags.append(tag)
    return ','.join(tags)

