           ca_cert=None, cert_key=None, cert_cert=None,
           timeout=None, protocol="http"):
    """Return an instance of an Etcd3Client."""
    return Etcd3Client(host, port, ca_cert, cert_key, cert_cert, timeout, protocol)

def apply_t0(self, hits):
        """Apply only t0s"""
        if HAVE_NUMBA:
            apply_t0_nb(
                hits.time, hits.dom_id, hits.channel_id, self._lookup_tables
            )
        else:
            n = len(hits)
            cal = np.empty(n)
            lookup = self._calib_by_dom_and_channel
            for i in range(n):
                calib = lookup[hits['dom_id'][i]][hits['channel_id'][i]]
                cal[i] = calib[6]
            hits.time += cal
        return hits

def apply_t0(self, hits):
        """Apply only t0s"""
        for hit in hits:
            self.apply_t0_hit(hit)

def add_transcript(self,tx):
      """add a single transcript"""
      candidates = tx.junctions
      targets = self.junctions
      matches = []
      for i in range(0,len(targets)):
         for j in range(0,len(candidates)):
            if targets[i].overlaps(candidates[j],self._tolerance):
               matches.append([i,j])
      if len(matches) != len(candidates): return
      if len(matches) > 1:
         if False in  [(matches[i+1][0]-matches[i][0])==1 and
                       (matches[i+1][1]-matches[i][1])==1 for i in range(0,len(matches)-1)]:
            return
      # nowe we can add them
      for m in matches:
         self._exon_groups[m[0]].add_exon(tx.exons[m[1]])
         self._exon_groups[m[0]+1].add_exon(tx.exons[m[1]+1])
      self._transcripts.append(tx)

def add_transcript(self,tx):
      """add a single transcript"""
      if tx.gene_id not in self.transcripts:
         self.transcripts[tx.gene_id] = []
      self.transcripts[tx.gene_id].append(tx)

def lookup_cert(self, key):
        """
        Search through keys
        """
        for k, v in self.keys.items():
            if k == key:
                return v
        return None

def complete(self):
        """ Return list of valid completions

            Returns a list of valid completions on the current level in the
            tree. If an element of type 'value' is found, its complete callback
            function is called (if set).
        """

        comp = []
        for k, v in self.key.items():

            # if we have reached a value, try to fetch valid completions
            if v['type'] == 'value':
                if 'complete' in v:
                    comp += v['complete'](self.inp_cmd[-1])

            # otherwise, k is our valid completion
            else:
                comp.append(k)

        return comp

def complete(self):
        """ Return list of valid completions

            Returns a list of valid completions on the current level in the
            tree. If an element of type 'value' is found, its complete callback
            function is called (if set).
        """
        completions = []
        for child in self.children:
            if child.type == 'value':
                if hasattr(child, 'complete'):
                    completions.extend(child.complete())
            else:
                completions.extend(child.complete())
        return completions

def qs_add(self, *args, **kwargs):
        """Add value to QuerySet MultiDict"""
        query = self.query.copy()
        if args:
            mdict = MultiDict(args[0])
            for k, v in mdict.items():
                query.add(k, v)
        for k, v in kwargs.items():
            query.add(k, v)
        return self._copy(query=query)

def qs_add(self, *args, **kwargs):
        """Add value to QuerySet MultiDict"""
        self.qs_data.add(*args, **kwargs)

def _exitOnSignal(sigName, message):
    """Handles a signal with sys.exit.

    Some of these signals (SIGPIPE, for example) don't exist or are invalid on
    Windows. So, ignore errors that might arise.
    """
    try:
        signal.signal(getattr(signal, sigName), lambda *args: sys.exit(1))
    except AttributeError:
        pass

def decrypt(self):
        """Decrypt decrypts the secret and returns the plaintext.

        Calling decrypt() may incur side effects such as a call to a remote service for decryption.
        """
        if not self._crypter:
            return b''
        try:
            plaintext = self._crypter.decrypt(self._ciphertext, **self._decrypt_params)
            return plaintext
        except Exception as e:
            exc_info = sys.exc_info()
            six.reraise(
                ValueError('Invalid ciphertext "%s", error: %s' % (self._ciphertext, e)),
                None,
                exc_info[2]
            )

def normalize_version(version):
    """
    Helper function to normalize version.
    Returns a comparable object.
    Args:
        version (str) version, e.g. "0.1.0"
    """
    rv = []
    for x in version.split("."):
        try:
            rv.append(int(x))
        except ValueError:
            for y in re.split("([0-9]+)", x):
                if y == '':
                    continue
                try:
                    rv.append(int(y))
                except ValueError:
                    rv.append(y)
    return rv

