def xml2dict(root):
    """Use functions instead of Class and remove namespace based on:
    http://stackoverflow.com/questions/2148119
    """
    output = {}
    if root.items():
        output.update(dict(root.items()))

    for element in root:
        if element:
            if len(element) == 1 or element[0].tag != element[1].tag:
                one_dict = xml2dict(element)
            else:
                one_dict = {ns(element[0].tag): xml2list(element)}

            if element.items():
                one_dict.update(dict(element.items()))
            output.update({ns(element.tag): one_dict})

        elif element.items():
            output.update({ns(element.tag): dict(element.items())})

        else:
            output.update({ns(element.tag): element.text})

    return output

def xml2dict(root):
    """Use functions instead of Class and remove namespace based on:
    http://stackoverflow.com/questions/2148119
    """
    if root.text is None:
        root.text = ""
    d = {root.tag: root.text}
    for child in root:
        d = dict(d, **xml2dict(child))
    return d

def parse_signature(signature):
    """Parse a signature into its input and return parameter types.

    This will also collect the types that are required by any of the input
    and return types.

    :sig: (str) -> Tuple[List[str], str, Set[str]]
    :param signature: Signature to parse.
    :return: Input parameter types, return type, and all required types.
    """
    input_types = []
    return_type = None
    required_types = set()

    for part in signature.split('->'):
        if '(' in part:
            input_types = [x.strip() for x in part.split('(')[1].split(',')]
        elif ')' in part:
            return_type = part.split(')')[0].strip()
        else:
            raise ValueError('Invalid signature: {}'.format(signature))

    for input_type in input_types:
        required_types.add(input_type)

    if return_type is not None:
        required_types.add(return_type)

    return input_types, return_type, required_types

