def newick(self):
        """Output this ``Tree`` as a Newick string

        Returns:
            ``str``: Newick string of this ``Tree``
        """
        if self.root.edge_length is None:
            suffix = ';'
        elif isinstance(self.root.edge_length,int):
            suffix = ':%d;' % self.root.edge_length
        elif isinstance(self.root.edge_length,float) and self.root.edge_length.is_integer():
            suffix = ':%d;' % int(self.root.edge_length)
        else:
            suffix = ':%s;' % str(self.root.edge_length)
        if self.is_rooted:
            return '[&R] %s%s' % (self.root.newick(),suffix)
        else:
            return '%s%s' % (self.root.newick(),suffix)

def newick(self):
        """Output this ``Tree`` as a Newick string

        Returns:
            ``str``: Newick string of this ``Tree``
        """
        return self.root.newick()

def widgets(self, include_clones=False):
        """
        Recursively gets the list of widgets.

        :param include_clones: True to retrieve all tabs, including clones,
            otherwise only original widgets are returned.
        """
        widgets = []
        for i in range(self.main_tab_widget.count()):
            widget = self.main_tab_widget.widget(i)
            try:
                if widget.original is None or include_clones:
                    widgets.append(widget)
            except AttributeError:
                pass
        for child in self.child_splitters:
            widgets += child.widgets(include_clones=include_clones)
        return widgets

def widgets(self, include_clones=False):
        """
        Recursively gets the list of widgets.

        :param include_clones: True to retrieve all tabs, including clones,
            otherwise only original widgets are returned.
        """
        widgets = []
        for widget in self.widgets:
            if isinstance(widget, Tab):
                widgets.extend(widget.widgets(include_clones=include_clones))
            else:
                widgets.append(widget)
        return widgets

def connect(self, protocol=None):
        """Initialize DAP IO pins for JTAG or SWD"""
        # Convert protocol to port enum.
        if protocol is not None:
            port = self.PORT_MAP[protocol]
        else:
            port = DAPAccess.PORT.DEFAULT

        try:
            self._link.connect(port)
        except DAPAccess.Error as exc:
            six.raise_from(self._convert_exception(exc), exc)

        # Read the current mode and save it.
        actualMode = self._link.get_swj_mode()
        self._protocol = self.PORT_MAP[actualMode]

        self._invalidate_cached_registers()

def connect(self, protocol=None):
        """Initialize DAP IO pins for JTAG or SWD"""
        if protocol is None:
            protocol = self.protocol
        if protocol == "jtag":
            self.dap.connect(protocol)
        elif protocol == "swd":
            self.dap.connect(protocol)
        else:
            raise ValueError("Invalid protocol")

