        """
        Return a HTTPResponse either of a PDF file or HTML.

        :rtype: HttpResponse
        """
        if request.GET.get('format') == 'pdf':
            return self.render_to_pdf(request)
        return super(PdfView, self).get(request, *args, **kwargs)

def contains(self, index: Union[SchemaKey, int, str]) -> bool:
        """
        Return whether the cache contains a schema for the input key, sequence number, or schema identifier.

        :param index: schema key, sequence number, or sequence identifier
        :return: whether the cache contains a schema for the input index
        """
        if isinstance(index, SchemaKey):
            return self._key_to_schema.get(index) is not None
        elif isinstance(index, int):
            return self._sequence_to_schema.get(index) is not None
        elif isinstance(index, str):
            return self._identifier_to_schema.get(index) is not None
        else:
            raise TypeError("index must be a SchemaKey, int, or str")

def MultiListChildren(self, urns):
    """Lists children of a bunch of given urns. Results are cached."""
    result = {}
    not_listed_urns = []

    for urn in urns:
      try:
        result[urn] = self._children_lists_cache[urn]
      except KeyError:
        not_listed_urns.append(urn)

    if not_listed_urns:
      for urn, children in FACTORY.MultiListChildren(not_listed_urns):
        result[urn] = self._children_lists_cache[urn] = children

      for urn in not_listed_urns:
        self._children_lists_cache.setdefault(urn, [])
        result.setdefault(urn, [])

    return result

def MultiListChildren(self, urns):
    """Lists children of a bunch of given urns. Results are cached."""
    if not urns:
      return []
    children = self._children_cache.get(urns)
    if children is None:
      children = self._ListChildren(urns)
      self._children_cache[urns] = children
    return children

def get_local_variable_or_declare_one(self, raw_name, type=None):
        """
        This function will first check if raw_name has been used to create some variables. If yes, the latest one
        named in self.variable_name_mapping[raw_name] will be returned. Otherwise, a new variable will be created and
        then returned.
        """
        if raw_name in self.variable_name_mapping:
            return self.variable_name_mapping[raw_name]
        else:
            if type is None:
                type = self.get_type_from_raw_name(raw_name)
            var = self.declare_variable(raw_name, type)
            self.variable_name_mapping[raw_name] = var
            return var

def _get_conn(self, host, port, afi):
        """Get or create a connection to a broker using host and port"""
        if host not in self._connections:
            self._connections[host] = {}
        if port not in self._connections[host]:
            self._connections[host][port] = {}
        if afi not in self._connections[host][port]:
            self._connections[host][port][afi] = {}
            self._connections[host][port][afi]["conn"] = self._create_conn(host, port, afi)
            self._connections[host][port][afi]["conn"].connect()
            self._connections[host][port][afi]["conn"].set_timeout(self._timeout)
            self._connections[host][port][afi]["conn"].set_keepalive(self._keepalive)
            self._connections[host][port][afi]["conn"].set_keepalive_timeout(self._keepalive_timeout)
            self._connections[host][port][afi]["conn"].set_keepalive_max_probes(self._keepalive_max_probes)
            self._connections[host][port][afi]["conn"].set_keepalive_probes_interval(self._keepalive_probes_interval)
            self._connections[host][port][afi]["conn"].set_keepalive_probes_count(self._keepalive_probes_count)
            self._connections[host][port][afi]["conn"].set_keepalive_probes_interval(self._keepalive_probes_interval)
            self._connections[host][port][afi]["conn"].set_keepalive_probes_count(self._keepalive_probes_count)
            self._connections[host][port][afi]["conn"].set_keepalive_probes_interval(self._keepalive_probes_interval)
            self._connections[host][port][afi]["conn"].set_keepalive_probes_count(self._keepalive_probes_count)
            self._connections[host][port][afi]["conn"].set_keepalive

def check_user_password(self, user, password=None, form=None):
        """Checks if the password matches the one of the user. If no password is
        provided, the current form will be used
        """
        pwcol = self.options['password_column']
        if password is None:
            if not form and "form" in current_context.data and request.method == "POST":
                form = current_context.data.form
            if form:
                password = form[pwcol].data
            else:
                raise OptionMissingError("Missing 'password' option or a form")
        current_pwd = getattr(user, pwcol)
        if not current_pwd or not self.bcrypt.check_password_hash(current_pwd, password):
            current_context.exit(trigger_action_group="password_mismatch")

def check_user_password(self, user, password=None, form=None):
        """Checks if the password matches the one of the user. If no password is
        provided, the current form will be used
        """
        if form is None:
            form = self.form_class(instance=user)
        if password is None:
            password = form.data.get('password')
        if password:
            if not user.check_password(password):
                raise forms.ValidationError(self.error_messages['password_mismatch'])
        return form

def open_font(self, name):
        """Open the font identifed by the pattern name and return its
        font object. If name does not match any font, None is returned."""
        for font in self.fonts:
            if font.match(name):
                return font
        return None

def get_ga_client_id(self):
        """
        Retrieve the client ID from the Google Analytics cookie, if available,
        and save in the current session
        """
        request = self.get_ga_request()
        if not request or not hasattr(request, 'session'):
            return super(GARequestErrorReportingMixin, self).get_ga_client_id()
        if 'ga_client_id' not in request.session:
            client_id = self.ga_cookie_re.match(request.COOKIES.get('_ga', ''))
            client_id = client_id and client_id.group('cid') or str(uuid.uuid4())
            request.session['ga_client_id'] = client_id
        return request.session['ga_client_id']

def do_extra_polishing(self):
        """
        Goes over each EXTRA_POLISH_FUNCTION to see if it applies to this page, if so, calls it
        """
        for f in self.EXTRA_POLISH_FUNCTIONS:
            if not hasattr(f, 'polish_commit_indexes'):
                if hasattr(f, 'polish_urls') and self.URL in f.polish_urls:
                    f()

            if not hasattr(f, 'polish_urls'):
                if hasattr(f, 'polish_commit_indexes') and self.CURRENT_COMMIT_INDEX in f.polish_commit_indexes:
                    f()

            if hasattr(f, 'polish_commit_indexes') and hasattr(f, 'polish_urls'):
                if self.URL in f.polish_urls and self.CURRENT_COMMIT_INDEX in f.polish_commit_indexes:
                    f()

def do_extra_polishing(self):
        """
        Goes over each EXTRA_POLISH_FUNCTION to see if it applies to this page, if so, calls it
        """
        for function in self.EXTRA_POLISH_FUNCTIONS:
            if function(self):
                function(self)

def _allow_custom_expire(self, load):
        """
        Return bool if requesting user is allowed to set custom expire
        """
        expire_override = self.opts.get('token_expire_user_override', False)

        if expire_override is True:
            return True

        if isinstance(expire_override, collections.Mapping):
            expire_whitelist = expire_override.get(load['eauth'], [])
            if isinstance(expire_whitelist, collections.Iterable):
                if load.get('username') in expire_whitelist:
                    return True

        return False

def parse_utuple(s,urx,length=2):
    """parse a string into a list of a uniform type"""
    if type(urx) != str:
        urx=urx.pattern;
    if length is not None and length < 1:
        raise ValueError("invalid length: {}".format(length));
    if length == 1:
        rx = r"^ *\( *{urx} *,? *\) *$".format(urx=urx);
    elif length is None:
        rx = r"^ *\( *(?:{urx} *, *)*{urx} *,? *\) *$".format(urx=urx);
    else:
        rx = r"^ *\( *(?:{urx} *, *){{{rep1}}}{urx} *,? *\) *$".format(
            rep1=length-1,
            urx=urx);
    return re.match(rx,s);

def parse_utuple(s,urx,length=2):
    """parse a string into a list of a uniform type"""
    return [urx.match(x).group(1) for x in s.split()[:length]]

def changeWorkflowState(content, wf_id, state_id, **kw):
    """Change the workflow state of an object
    @param content: Content obj which state will be changed
    @param state_id: name of the state to put on content
    @param kw: change the values of same name of the state mapping
    @return: True if succeed. Otherwise, False
    """
    portal_workflow = api.get_tool("portal_workflow")
    workflow = portal_workflow.getWorkflowById(wf_id)
    if not workflow:
        logger.error("%s: Cannot find workflow id %s" % (content, wf_id))
        return False

    wf_state = {
        'action': kw.get("action", None),
        'actor': kw.get("actor", api.get_current_user().id),
        'comments': "Setting state to %s" % state_id,
        'review_state': state_id,
        'time': DateTime()
    }

    # Change status and update permissions
    portal_workflow.setStatusOf(wf_id, content, wf_state)
    workflow.updateRoleMappingsFor(content)

    # Map changes to catalog
    indexes = ["allowedRolesAndUsers", "review_state", "is_active"]
    content.reindexObject(idxs=indexes)
    return True

def changeWorkflowState(content, wf_id, state_id, **kw):
    """Change the workflow state of an object
    @param content: Content obj which state will be changed
    @param state_id: name of the state to put on content
    @param kw: change the values of same name of the state mapping
    @return: True if succeed. Otherwise, False
    """
    wf_state = getToolByName(content, 'portal_workflow')
    wf_state.doActionFor(content, state_id, **kw)
    return True

def _setup_storage_dir(self):
        """Setup the storage directory path value and ensure the path exists.

        :rtype: str
        :raises: tinman.exceptions.ConfigurationException

        """
        dir_path = self._settings.get(config.DIRECTORY)
        if dir_path is None:
            dir_path = self._default_path
            if not os.path.exists(dir_path):
                self._make_path(dir_path)
        else:
            dir_path = path.abspath(dir_path)
            if not os.path.exists(dir_path) or not os.path.isdir(dir_path):
                raise exceptions.ConfigurationException(self.__class__.__name__,
                                                        config.DIRECTORY)
        return dir_path.rstrip('/')

def render(raw_config, environment=None):
    """Renders a config, using it as a template with the environment.

    Args:
        raw_config (str): the raw stacker configuration string.
        environment (dict, optional): any environment values that should be
            passed to the config

    Returns:
        str: the stacker configuration populated with any values passed from
            the environment

    """

    t = Template(raw_config)
    buff = StringIO()
    if not environment:
        environment = {}
    try:
        substituted = t.substitute(environment)
    except KeyError as e:
        raise exceptions.MissingEnvironment(e.args[0])
    except ValueError:
        # Support "invalid" placeholders for lookup placeholders.
        substituted = t.safe_substitute(environment)

    if not isinstance(substituted, str):
        substituted = substituted.decode('utf-8')

    buff.write(substituted)
    buff.seek(0)
    return buff.read()

def recursive_model_update(model, props):
    """
    Recursively updates attributes on a model including other
    models. If the type of the new model matches the old model
    properties are simply updated, otherwise the model is replaced.
    """
    updates = {}
    valid_properties = model.properties_with_values()
    for k, v in props.items():
        if isinstance(v, Model):
            nested_model = getattr(model, k)
            if type(v) is type(nested_model):
                nested_props = v.properties_with_values(include_defaults=False)
                recursive_model_update(nested_model, nested_props)
            else:
                setattr(model, k, v)
        elif k in valid_properties and v != valid_properties[k]:
            updates[k] = v
    model.update(**updates)

def recursive_model_update(model, props):
    """
    Recursively updates attributes on a model including other
    models. If the type of the new model matches the old model
    properties are simply updated, otherwise the model is replaced.
    """
    for key, value in props.items():
        if isinstance(value, dict):
            if key in model:
                if isinstance(model[key], dict):
                    recursive_model_update(model[key], value)
                else:
                    model[key] = recursive_model_update(model[key], value)
            else:
                model[key] = recursive_model_update(model, value)
        else:
            model[key] = value
    return model

def contains_version(self, version):
        """Returns True if version is contained in this range."""
        if len(self.bounds) < 5:
            # not worth overhead of binary search
            for bound in self.bounds:
                i = bound.version_containment(version)
                if i == 0:
                    return True
                if i == -1:
                    return False
        else:
            _, contains = self._contains_version(version)
            return contains

        return False

def contains_version(self, version):
        """Returns True if version is contained in this range."""
        return self.lower <= version <= self.upper

def dynamize_last_evaluated_key(self, last_evaluated_key):
        """
        Convert a last_evaluated_key parameter into the data structure
        required for Layer1.
        """
        d = None
        if last_evaluated_key:
            hash_key = last_evaluated_key['HashKeyElement']
            d = {'HashKeyElement': self.dynamize_value(hash_key)}
            if 'RangeKeyElement' in last_evaluated_key:
                range_key = last_evaluated_key['RangeKeyElement']
                d['RangeKeyElement'] = self.dynamize_value(range_key)
        return d

def dynamize_last_evaluated_key(self, last_evaluated_key):
        """
        Convert a last_evaluated_key parameter into the data structure
        required for Layer1.
        """
        if last_evaluated_key is None:
            return None
        return {
            'ExclusiveStartKey': last_evaluated_key
        }

def parse(self):
        """Parse the table data string into records."""
        self.records = []
        for line in self.data.splitlines():
            if line.startswith('#'):
                continue
            if line.strip() == '':
                continue
            self.records.append(self.parse_line(line))

def has_colors (fp):
    """Test if given file is an ANSI color enabled tty."""
    # The is_tty() function ensures that we do not colorize
    # redirected streams, as this is almost never what we want
    if not is_tty(fp):
        return False
    if os.name == 'nt':
        return True
    elif has_curses:
        import curses
        try:
            curses.setupterm(os.environ.get("TERM"), fp.fileno())
            # More than 8 colors are good enough.
            return curses.tigetnum("colors") >= 8
        except curses.error:
            return False
    return False

def has_colors (fp):
    """Test if given file is an ANSI color enabled tty."""
    return fp.isatty() and hasattr(fp, "fileno") and os.isatty(fp.fileno())

def load_json(filename: str) -> Union[List, Dict]:
    """Load JSON data from a file and return as dict or list.

    Defaults to returning empty dict if file is not found.
    """
    try:
        with open(filename, encoding='utf-8') as fdesc:
            return json.loads(fdesc.read())
    except FileNotFoundError:
        # This is not a fatal error
        _LOGGER.debug('JSON file not found: %s', filename)
    except ValueError as error:
        _LOGGER.exception('Could not parse JSON content: %s', filename)
        raise PytradfriError(error)
    except OSError as error:
        _LOGGER.exception('JSON file reading failed: %s', filename)
        raise PytradfriError(error)
    return {}

def load_json(filename: str) -> Union[List, Dict]:
    """Load JSON data from a file and return as dict or list.

    Defaults to returning empty dict if file is not found.
    """
    try:
        with open(filename) as f:
            return json.load(f)
    except FileNotFoundError:
        return {}

def default_links_pagination_factory(page, urlkwargs):
    """Factory for record links generation."""
    endpoint = '.communities_list'

    links = {
        'self': url_for(endpoint, page=page.page, _external=True, **urlkwargs),
    }

    if page.has_prev:
        links['prev'] = url_for(endpoint, page=page.prev_num, _external=True,
                                **urlkwargs)
    if page.has_next:
        links['next'] = url_for(endpoint, page=page.next_num, _external=True,
                                **urlkwargs)

    return links

