def matches(self, stream):
        """Check if this selector matches the given stream

        Args:
            stream (DataStream): The stream to check

        Returns:
            bool: True if this selector matches the stream
        """

        if self.match_type != stream.stream_type:
            return False

        if self.match_id is not None:
            return self.match_id == stream.stream_id

        if self.match_spec == DataStreamSelector.MatchUserOnly:
            return not stream.system
        elif self.match_spec == DataStreamSelector.MatchSystemOnly:
            return stream.system
        elif self.match_spec == DataStreamSelector.MatchUserAndBreaks:
            return (not stream.system) or (stream.system and (stream.stream_id in DataStream.KnownBreakStreams))

        # The other case is that match_spec is MatchCombined, which matches everything
        # regardless of system of user flag
        return True

def _number_desc_by_type(metadata, num_type):
    """Return the PhoneNumberDesc of the metadata for the given number type"""
    if num_type == PhoneNumberType.PREMIUM_RATE:
        return metadata.premium_rate
    elif num_type == PhoneNumberType.TOLL_FREE:
        return metadata.toll_free
    elif num_type == PhoneNumberType.MOBILE:
        return metadata.mobile
    elif (num_type == PhoneNumberType.FIXED_LINE or
          num_type == PhoneNumberType.FIXED_LINE_OR_MOBILE):
        return metadata.fixed_line
    elif num_type == PhoneNumberType.SHARED_COST:
        return metadata.shared_cost
    elif num_type == PhoneNumberType.VOIP:
        return metadata.voip
    elif num_type == PhoneNumberType.PERSONAL_NUMBER:
        return metadata.personal_number
    elif num_type == PhoneNumberType.PAGER:
        return metadata.pager
    elif num_type == PhoneNumberType.UAN:
        return metadata.uan
    elif num_type == PhoneNumberType.VOICEMAIL:
        return metadata.voicemail
    else:
        return metadata.general_desc

def _number_desc_by_type(metadata, num_type):
    """Return the PhoneNumberDesc of the metadata for the given number type"""
    for desc in metadata.phone_number_metadata.number_format:
        if desc.type == num_type:
            return desc
    raise ValueError("No PhoneNumberDesc found for number type %s" % num_type)

def mod_watch(name, **kwargs):
    """
    The at watcher, called to invoke the watch command.

    .. note::
        This state exists to support special handling of the ``watch``
        :ref:`requisite <requisites>`. It should not be called directly.

        Parameters for this function should be set by the state being triggered.

    name
        The name of the atjob

    """
    ret = {"name": name, "changes": {}, "result": True, "comment": ""}

    if __opts__["test"]:
        ret["comment"] = "At job {} is set to be added".format(name)
        ret["changes"] = {name: "Added"}
        ret["result"] = None
        return ret

    if __salt__["at.watch"](name, **kwargs):
        ret["comment"] = "At job {} has been added".format(name)
        ret["changes"] = {name: "Added"}
    else:
        ret["comment"] = "At job {} failed to be added".format(name)
        ret["result"] = False
    return ret

def in_interactive_session():
    """ check if we're running in an interactive shell

    returns True if running under python/ipython interactive shell
    """
    from pandas import get_option

    def check_main():
        try:
            import __main__ as main
        except ModuleNotFoundError:
            return get_option('mode.sim_interactive')
        return (not hasattr(main, '__file__') or
                get_option('mode.sim_interactive'))

    try:
        return __IPYTHON__ or check_main()  # noqa
    except NameError:
        return check_main()

def in_interactive_session():
    """ check if we're running in an interactive shell

    returns True if running under python/ipython interactive shell
    """
    return not hasattr(sys, 'ps1')

def _is_type(self, instance, type):
        """
        Check if an ``instance`` is of the provided (JSON Schema) ``type``.
        """
        if type not in self._types:
            raise UnknownType(type)
        type = self._types[type]

        # bool inherits from int, so ensure bools aren't reported as integers
        if isinstance(instance, bool):
            type = _flatten(type)
            if int in type and bool not in type:
                return False
        return isinstance(instance, type)

def _is_type(self, instance, type):
        """
        Check if an ``instance`` is of the provided (JSON Schema) ``type``.
        """
        if type == 'array':
            return isinstance(instance, list)
        elif type == 'boolean':
            return isinstance(instance, bool)
        elif type == 'integer':
            return isinstance(instance, int)
        elif type == 'number':
            return isinstance(instance, (int, float))
        elif type == 'null':
            return instance is None
        elif type == 'object':
            return isinstance(instance, dict)
        elif type == 'string':
            return isinstance(instance, str)
        else:
            raise ValueError('Unknown type: {}'.format(type))

def __parseKeyValueStore(self, data):
        """Returns a dictionary filled with the keys and values of the key value store"""
        keyValueStore = {}
        for key in data.keys():
            keyValueStore[key] = data[key]
        return keyValueStore

def write_model_map(self, model_name=None, name=None):
        """Save counts model map to a FITS file.

        """
        if model_name is None:
            model_name = self.model_name
        if name is None:
            name = self.name
        if self.model_map is None:
            raise ValueError('No model map to save.')
        if model_name is None:
            raise ValueError('No model name specified.')
        if name is None:
            raise ValueError('No name specified.')
        model_map_file = self.model_map_file(model_name, name)
        self.logger.info('Writing model map to {}'.format(model_map_file))
        self.model_map.write(model_map_file, overwrite=True)

def prepareQueryTerm(self, field, term):
        """Prepare a query term for inclusion in a query.

        This escapes the term and if necessary, wraps the term in quotes.

        """
        if term == "*":
            return term
        addstar = False
        if term[len(term) - 1] == '*':
            addstar = True
            term = term[0 : len(term) - 1]
        term = self.escapeQueryTerm(term)
        if addstar:
            term = '%s*' % term
        if self.getSolrType(field) in ['string', 'text', 'text_ws']:
            return '"%s"' % term
        return term

def prepareQueryTerm(self, field, term):
        """Prepare a query term for inclusion in a query.

        This escapes the term and if necessary, wraps the term in quotes.

        """
        if term is None:
            return None
        if isinstance(term, unicode):
            term = term.encode('utf-8')
        if self.escapeTerms:
            term = self.escapeTerm(term)
        if self.useQuotes:
            term = self.quoteTerm(term)
        return term

def get_result(self, line):
        """Gets work item name and id."""
        res = self.RESULT_SEARCH.search(line)
        try:
            name, ids = res.group(1), res.group(2)
        except (AttributeError, IndexError):
            return None

        ids = ids.split("/")
        tc_id = ids[0]
        try:
            custom_id = ids[1]
        except IndexError:
            custom_id = None
        return LogItem(name, tc_id, custom_id)

def get_result(self, line):
        """Gets work item name and id."""
        result = re.search(r'(?<=Work Item: )\w+', line)
        if result:
            return result.group()
        return None

def delete_group_action(model, request):
    """Delete group from database.
    """
    try:
        groups = model.parent.backend
        uid = model.model.name
        del groups[uid]
        groups()
        model.parent.invalidate()
    except Exception as e:
        return {
            'success': False,
            'message': str(e)
        }
    localizer = get_localizer(request)
    message = localizer.translate(_(
        'deleted_group',
        default='Deleted group from database'
    ))
    return {
        'success': True,
        'message': message
    }

def delete_group_action(model, request):
    """Delete group from database.
    """
    group = model.objects.get(id=request.POST.get('id'))
    group.delete()
    return HttpResponseRedirect(reverse('admin:index'))

def media(self, form):
        """
        Collects admin and form media.
        """
        js = ['admin/js/core.js', 'admin/js/admin/RelatedObjectLookups.js',
              'admin/js/jquery.min.js', 'admin/js/jquery.init.js']

        media = forms.Media(
            js=['%s%s' % (settings.STATIC_URL, u) for u in js],
        )

        if form:
            for name, field in form.fields.items():
                media = media + field.widget.media

        return media

def guess_decode(text):
    """Decode *text* with guessed encoding.

    First try UTF-8; this should fail for non-UTF-8 encodings.
    Then try the preferred locale encoding.
    Fall back to latin-1, which always works.
    """
    try:
        return text.decode('utf-8')
    except UnicodeDecodeError:
        pass
    try:
        return text.decode(locale.getpreferredencoding())
    except UnicodeDecodeError:
        pass
    return text.decode('latin-1')

def store_magic_envelope_doc(self, payload):
        """Get the Magic Envelope, trying JSON first."""
        try:
            json_payload = json.loads(decode_if_bytes(payload))
        except ValueError:
            # XML payload
            xml = unquote(decode_if_bytes(payload))
            xml = xml.lstrip().encode("utf-8")
            logger.debug("diaspora.protocol.store_magic_envelope_doc: xml payload: %s", xml)
            self.doc = etree.fromstring(xml)
        else:
            logger.debug("diaspora.protocol.store_magic_envelope_doc: json payload: %s", json_payload)
            self.doc = self.get_json_payload_magic_envelope(json_payload)

def store_magic_envelope_doc(self, payload):
        """Get the Magic Envelope, trying JSON first."""
        try:
            return json.loads(payload)
        except ValueError:
            return payload

def host_to_ips(host):
    """
    Returns a list of IP addresses of a given hostname or None if not found.
    """
    ips = []
    try:
        for family, socktype, proto, canonname, sockaddr in socket.getaddrinfo(
                host, 0, socket.AF_UNSPEC, socket.SOCK_STREAM):
            if family == socket.AF_INET:
                ip, port = sockaddr
            elif family == socket.AF_INET6:
                ip, port, flow_info, scope_id = sockaddr
            ips.append(ip)
        if not ips:
            ips = None
    except Exception:
        ips = None
    return ips

def host_to_ips(host):
    """
    Returns a list of IP addresses of a given hostname or None if not found.
    """
    try:
        return [str(ip) for ip in socket.gethostbyname_ex(host)[2]]
    except socket.gaierror:
        return None

def get_xritdecompress_outfile(stdout):
    """Analyse the output of the xRITDecompress command call and return the file."""
    outfile = b''
    for line in stdout:
        try:
            k, v = [x.strip() for x in line.split(b':', 1)]
        except ValueError:
            break
        if k == b'Decompressed file':
            outfile = v
            break

    return outfile

def get_xritdecompress_outfile(stdout):
    """Analyse the output of the xRITDecompress command call and return the file."""
    for line in stdout.splitlines():
        if line.startswith("Output file:"):
            return line.split(":")[1].strip()
    return None

def SetEncoding(sval):
    """Sets the encoding variable according to the text passed

    :param sval: text specification for the desired model
    """
    global encoding
    s=sval.lower()
    if s == "additive":
        encoding = Encoding.Additive
    elif s == "dominant":
        encoding = Encoding.Dominant
    elif s == "recessive":
        encoding = Encoding.Recessive
    elif s == "genotype":
        encoding = Encoding.Genotype
    elif s == "raw":
        encoding = Encoding.Raw
    else:
        raise InvalidSelection("Invalid encoding, %s, selected" % (sval))

def SetEncoding(sval):
    """Sets the encoding variable according to the text passed

    :param sval: text specification for the desired model
    """
    global encoding
    if sval == "utf-8":
        encoding = "utf-8"
    elif sval == "latin-1":
        encoding = "latin-1"
    elif sval == "ascii":
        encoding = "ascii"
    else:
        print("Encoding not recognized, using utf-8")
        encoding = "utf-8"

def sync(self):
        """Commit deferred writes to file."""
        for key_hash, obj in six.iteritems(self._cache):
            # Objects are checked for expiration in __getitem__,
            # but we can check here to avoid unnecessary writes.
            if not obj.has_expired():
                file_path = self._path_for_hash(key_hash)
                with open(str(file_path), self._write_mode) as f:
                    obj.dump(f)

def sync(self):
        """Commit deferred writes to file."""
        self.file.flush()

def __deserialize_model(self, data, klass):
        """
        Deserializes list or dict to model.

        :param data: dict, list.
        :param klass: class literal.
        :return: model object.
        """
        if data is None:
            return None

        if isinstance(data, list):
            return [self.__deserialize_model(x, klass) for x in data]
        elif isinstance(data, dict):
            return klass(**data)
        else:
            return data

def find_model(object):
        """
        Returns the model(s) associated with given object.

        :param object: Node / Attribute.
        :type object: GraphModelNode or GraphModelAttribute
        :return: Model(s).
        :rtype: list
        """

        models = []
        for model in GraphModel._GraphModel__models_instances.itervalues():
            for node in foundations.walkers.nodes_walker(model.root_node):
                if node is object:
                    models.append(model)

                for attribute in node.get_attributes():
                    if attribute is object:
                        models.append(model)
        return models

def delete_zombie_actions(self):
        """Remove actions that have a zombie status (usually timeouts)

        :return: None
        """
        id_to_del = []
        for act in list(self.actions.values()):
            if act.status == ACT_STATUS_ZOMBIE:
                id_to_del.append(act.uuid)
        # une petite tape dans le dos et tu t'en vas, merci...
        # *pat pat* GFTO, thks :)
        for a_id in id_to_del:
            del self.actions[a_id]

def delete_zombie_actions(self):
        """Remove actions that have a zombie status (usually timeouts)

        :return: None
        """
        for action in self.actions.values():
            if action.status == 'zombie':
                self.actions.pop(action.id)

def contains_plural_field(model, fields):
    """ Returns a boolean indicating if ``fields`` contains a relationship to multiple items. """
    source_model = model
    for orm_path in fields:
        model = source_model
        bits = orm_path.lstrip('+-').split('__')
        for bit in bits[:-1]:
            field = model._meta.get_field(bit)
            if field.many_to_many or field.one_to_many:
                return True
            model = get_model_at_related_field(model, bit)
    return False

def contains_plural_field(model, fields):
    """ Returns a boolean indicating if ``fields`` contains a relationship to multiple items. """
    return any(field.is_relation and field.related_model and field.related_model.is_plural for field in fields)

def _inputrc_enables_vi_mode():
    """
    Emulate a small bit of readline behavior.

    Returns:
        (bool) True if current user enabled vi mode ("set editing-mode vi") in .inputrc
    """
    for filepath in (os.path.expanduser('~/.inputrc'), '/etc/inputrc'):
        try:
            with open(filepath) as f:
                for line in f:
                    if _setre.fullmatch(line):
                        return True
        except IOError:
            continue
    return False

def _parse_ergodic_cutoff(self):
        """Get a numeric value from the ergodic_cutoff input,
        which can be 'on' or 'off'.
        """
        ec_is_str = isinstance(self.ergodic_cutoff, str)
        if ec_is_str and self.ergodic_cutoff.lower() == 'on':
            if self.sliding_window:
                return 1.0 / self.lag_time
            else:
                return 1.0
        elif ec_is_str and self.ergodic_cutoff.lower() == 'off':
            return 0.0
        else:
            return self.ergodic_cutoff

