def _start_scan(self, active):
        """Begin scanning forever
        """

        success, retval = self._set_scan_parameters(active=active)
        if not success:
            return success, retval

        try:
            response = self._send_command(6, 2, [2])
            if response.payload[0] != 0:
                self._logger.error('Error starting scan for devices, error=%d', response.payload[0])
                return False, {'reason': "Could not initiate scan for ble devices, error_code=%d, response=%s" % (response.payload[0], response)}
        except InternalTimeoutError:
            return False, {'reason': "Timeout waiting for response"}

        return True, None

def runner(queue, parallel):
    """Run individual jobs on an existing queue.
    """
    def run(fn_name, items):
        logger.info("clusterk: %s" % fn_name)
        assert "wrapper" in parallel, "Clusterk requires bcbio-nextgen-vm wrapper"
        fn = getattr(__import__("{base}.clusterktasks".format(base=parallel["module"]),
                                fromlist=["clusterktasks"]),
                     parallel["wrapper"])
        wrap_parallel = {k: v for k, v in parallel.items() if k in set(["fresources", "pack"])}
        out = []
        for data in [fn(fn_name, queue, parallel.get("wrapper_args"), wrap_parallel, x) for x in items]:
            if data:
                out.extend(data)
        return out
    return run

def runner(queue, parallel):
    """Run individual jobs on an existing queue.
    """
    while True:
        try:
            job = queue.get()
        except Exception as e:
            print(e)
            continue

        if job is None:
            break

        if parallel:
            job.run()
        else:
            job.run_serial()

        queue.task_done()

def _get_entref(bpe):
        """Returns the entity reference of an entity if it exists or
        return the entity reference that was passed in as argument."""
        if not _is_reference(bpe):
            try:
                er = bpe.getEntityReference()
            except AttributeError:
                return None
            return er
        else:
            return bpe

def _get_entref(bpe):
        """Returns the entity reference of an entity if it exists or
        return the entity reference that was passed in as argument."""
        if bpe.entity_reference is None:
            return bpe.entity_id
        else:
            return bpe.entity_reference

def server_thread(sock, handle_conn, quit_event):
    """Run a server on the specified socket."""
    while not quit_event.is_set():
        try:
            conn, addr = sock.accept()
        except socket.timeout:
            continue
        except socket.error:
            if quit_event.is_set():
                break
            else:
                raise
        else:
            handle_conn(conn, addr)

def get(self, key):
        """Get a value from the cache.

        If the |MICE| cannot be found in this cache, try and find it in the
        parent cache.
        """
        try:
            return self._cache[key]
        except KeyError:
            if self._parent is not None:
                return self._parent.get(key)
            raise KeyError(key)

def post_request(self, container, resource=None, params=None, accept=None):
        """Send a POST request."""
        url = self.make_url(container, resource)
        headers = self._make_headers(accept)

        try:
            rsp = requests.post(url, data=params, headers=headers,
                                verify=self._verify, timeout=self._timeout)
        except requests.exceptions.ConnectionError as e:
            RestHttp._raise_conn_error(e)

        if self._dbg_print:
            self.__print_req('POST', rsp.url, headers, params)

        return self._handle_response(rsp)

def post_request(self, container, resource=None, params=None, accept=None):
        """Send a POST request."""
        return self._request(container, resource, params, accept, 'POST')

async def get_data(self, raw: bool=True) -> AnyStr:
        """Return the body data."""
