def format_string_values(obj, err_fallback=(IndexError, KeyError), *args, **kwargs):
    """
    Format all string values in an object.
    Return the updated object
    """
    if isinstance(obj, dict):
        new = {}
        for key in obj.keys():
            new[key] = format_string_values(obj[key], *args, **kwargs)
        return new
    elif isinstance(obj, list):
        new = []
        for item in obj:
            new.append(format_string_values(item, *args, **kwargs))
        return new
    elif isinstance(obj, six.string_types):
        try:
            return obj.format(*args, **kwargs)
        except err_fallback:
            return obj
    else:
        return obj

def format_string_values(obj, err_fallback=(IndexError, KeyError), *args, **kwargs):
    """
    Format all string values in an object.
    Return the updated object
    """
    if isinstance(obj, dict):
        return {k: format_string_values(v, err_fallback, *args, **kwargs) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [format_string_values(v, err_fallback, *args, **kwargs) for v in obj]
    elif isinstance(obj, str):
        return format_string(obj, *args, **kwargs)
    elif isinstance(obj, (int, float)):
        return obj
    else:
        return obj

def draw(self, clear=True):
        """Draw each visible mesh in the scene from the perspective of the scene's camera and lit by its light."""
        if clear:
            self.clear()

        with self.gl_states, self.camera, self.light:
            for mesh in self.meshes:
                try:
                    mesh.draw()
                except AttributeError:
                    pass

def draw(self, clear=True):
        """Draw each visible mesh in the scene from the perspective of the scene's camera and lit by its light."""
        if clear:
            self.clear()
        for mesh in self.meshes:
            if mesh.visible:
                mesh.draw()

def manage_initial_service_status_brok(self, b):
        """Prepare the known services cache"""
        host_name = b.data['host_name']
        service_description = b.data['service_description']
        service_id = host_name+"/"+service_description
        logger.debug("got initial service status: %s", service_id)

        if host_name not in self.hosts_cache:
            logger.error("initial service status, host is unknown: %s.", service_id)
            return

        self.services_cache[service_id] = {
        }
        if 'customs' in b.data:
            self.services_cache[service_id]['_GRAPHITE_POST'] = \
                sanitize_name(b.data['customs'].get('_GRAPHITE_POST', None))

        logger.debug("initial service status received: %s", service_id)

