def _get_ref(repo, name):
    """
    Return ref tuple if ref is in the repo.
    """
    if name == 'base':
        name = repo['base']
    if name == repo['base'] or name in envs():
        if repo['branch_method'] == 'branches':
            return _get_branch(repo['repo'], name) \
                or _get_tag(repo['repo'], name)
        elif repo['branch_method'] == 'bookmarks':
            return _get_bookmark(repo['repo'], name) \
                or _get_tag(repo['repo'], name)
        elif repo['branch_method'] == 'mixed':
            return _get_branch(repo['repo'], name) \
                or _get_bookmark(repo['repo'], name) \
                or _get_tag(repo['repo'], name)
    return False

def _get_ref(repo, name):
    """
    Return ref tuple if ref is in the repo.
    """
    for ref in repo.refs:
        if ref.name == name:
            return ref
    return None

def validate_time_range(form, field):
    """ Makes sure the form data is in 'hh:mm - hh:mm' format and  the start time is less than end time."""
    try:
        start_time, end_time = field.data.split(' - ')
    except ValueError:
        raise ValidationError('Invalid time range.')

    if not start_time.isdigit() or not end_time.isdigit():
        raise ValidationError('Invalid time range.')

    start_time = int(start_time)
    end_time = int(end_time)

    if start_time > end_time:
        raise ValidationError('Start time should be less than end time.')

def find_whitespace_pattern(self):
        """
        Try to find a whitespace pattern in the existing parameters
        to be applied to a newly added parameter
        """
        name_ws = []
        value_ws = []
        for entry in self._entries:
            name_ws.append(get_whitespace(entry.name))
            if entry.value != '':
                value_ws.append(get_whitespace(entry._value))  # _value is unstripped
        if len(value_ws) >= 1:
            value_ws = most_common(value_ws)
        else:
            value_ws = ('', ' ')
        if len(name_ws) >= 1:
            name_ws = most_common(name_ws)
        else:
            name_ws = (' ', '')
        return name_ws, value_ws

def find_whitespace_pattern(self):
        """
        Try to find a whitespace pattern in the existing parameters
        to be applied to a newly added parameter
        """
        for param in self.parameters:
            if param.whitespace_pattern is not None:
                return param.whitespace_pattern
        return None

def dirinfo(path, opts=None):
    """
    Return information on a directory located on the Moose

    CLI Example:

    .. code-block:: bash

        salt '*' moosefs.dirinfo /path/to/dir/ [-[n][h|H]]
    """
    if opts is None:
        opts = {}

    cmd = "dirinfo {0}".format(path)

    if "n" in opts:
        cmd += " -n"
    if "h" in opts:
        cmd += " -h"
    if "H" in opts:
        cmd += " -H"

    return __salt__["cmd.run"](cmd, python_shell=False)

def get_input(params: Union[dict, list]) -> Tuple[list, dict]:
    """
    Get positional or keyword arguments from JSON RPC params

    :param params: Parameters passed through JSON RPC
    :return: args, kwargs
    """
    if isinstance(params, list):
        args = params
        kwargs = {}
    elif isinstance(params, dict):
        args = []
        kwargs = params
    else:
        raise TypeError("Params must be a list or a dict")
    return args, kwargs

def _send_mbus(self, frame):
        """Send modbus frame

        :param frame: modbus frame to send (with MBAP for TCP/CRC for RTU)
        :type frame: str (Python2) or class bytes (Python3)
        :returns: number of bytes send or None if error
        :rtype: int or None
        """
        if self._transport is None:
            return None
        if self._transport.is_open():
            try:
                self._transport.write(frame)
                return len(frame)
            except Exception as e:
                _LOGGER.error("Error sending frame: %s", e)
                return None
        else:
            _LOGGER.error("Transport is not open")
            return None

def _create_put_request(self, resource, billomat_id, command=None, send_data=None):
        """
        Creates a put request and return the response data
        """
        assert (isinstance(resource, str))

        if isinstance(billomat_id, int):
            billomat_id = str(billomat_id)

        if not command:
            command = ''
        else:
            command = '/' + command

        response = self.session.put(
            url=self.api_url + resource + '/' + billomat_id + command,
            data=json.dumps(send_data),
        )

        return self._handle_response(response)

def _create_put_request(self, resource, billomat_id, command=None, send_data=None):
        """
        Creates a put request and return the response data
        """
        if command is None:
            command = "PUT"
        if send_data is None:
            send_data = {}
        if billomat_id is None:
            billomat_id = ""
        else:
            billomat_id = "/" + str(billomat_id)
        url = self.base_url + resource + billomat_id
        return self._create_request(url, command, send_data)

def props(obj, required_args=None, **kwargs):
    """ Return a dictionary built from the combination of defaults, kwargs,
    and the attributes of the given object.
    """
    defaults = {}
    for key, value in obj.__dict__.items():
        if key.startswith('_'):
            continue
        defaults[key] = value
    if required_args is not None:
        for key in required_args:
            if key not in defaults:
                raise ValueError("Required argument %s not found" % key)
    return dict(defaults, **kwargs)

def _check_value_recursively(key, val, haystack):
    """
    Check if there is key _key_ with value _val_ in the given dictionary.
    ..warning:
        This is geared at JSON dictionaries, so some corner cases are ignored,
        we assume all iterables are either arrays or dicts
    """
    if isinstance(haystack, list):
        return any([_check_value_recursively(key, val, l) for l in haystack])
    elif isinstance(haystack, dict):
        if not key in haystack:
            return any([_check_value_recursively(key, val, d) for k, d in haystack.items()
                        if isinstance(d, list) or isinstance(d, dict)])
        else:
            return haystack[key] == val
    else:
        return False

def _check_value_recursively(key, val, haystack):
    """
    Check if there is key _key_ with value _val_ in the given dictionary.
    ..warning:
        This is geared at JSON dictionaries, so some corner cases are ignored,
        we assume all iterables are either arrays or dicts
    """
    if key in haystack:
        if val == haystack[key]:
            return True
        elif isinstance(val, dict):
            if isinstance(haystack[key], dict):
                return _check_value_recursively(val, haystack[key])
            else:
                return False
        elif isinstance(val, list):
            if isinstance(haystack[key], list):
                return _check_value_recursively(val, haystack[key])
            else:
                return False
        else:
            return False
    else:
        return False

def cleanup():
    """Must be called before exit"""
    temp_dirs = []
    for key in ('headless', 'headed'):
        if FIREFOX_INSTANCE[key] is not None:
            if FIREFOX_INSTANCE[key].profile:
                temp_dirs.append(FIREFOX_INSTANCE[key].profile.profile_dir)
            try:
                FIREFOX_INSTANCE[key].quit()
                FIREFOX_INSTANCE[key] = None
            except:
                logger.exception(
                    "Exception occurred in browser cleanup"
                )
    for temp_dir in temp_dirs:
        shutil.rmtree(temp_dir, ignore_errors=True)

def _assert_in_buildroot(self, filepath):
    """Raises an error if the given filepath isn't in the buildroot.

    Returns the normalized, absolute form of the path.
    """
    if not os.path.isabs(filepath):
      filepath = os.path.join(self.buildroot, filepath)
    if not filepath.startswith(self.buildroot):
      raise ValueError(
          'Filepath %s is not in the buildroot %s' % (filepath, self.buildroot))
    return os.path.normpath(filepath)

def add(self, interval):
        """
        Returns self after adding the interval and balancing.
        """
        if self.center_hit(interval):
            self.s_center.add(interval)
            return self
        else:
            direction = self.hit_branch(interval)
            if not self[direction]:
                self[direction] = Node.from_interval(interval)
                self.refresh_balance()
                return self
            else:
                self[direction] = self[direction].add(interval)
                return self.rotate()

def build_etag(self, response, include_etag=True, **kwargs):
        """
        Add an etag to the response body.

        Uses spooky where possible because it is empirically fast and well-regarded.

        See: http://blog.reverberate.org/2012/01/state-of-hash-functions-2012.html

        """
        if not include_etag:
            return

        if not spooky:
            # use built-in md5
            response.add_etag()
            return

        # use spooky
        response.headers["ETag"] = quote_etag(
            hexlify(
                spooky.hash128(
                    response.get_data(),
                ).to_bytes(16, "little"),
            ).decode("utf-8"),
        )

def add_predicate(self, key, value, predicate_type='equals'):
        """
        add key, value, type combination of a predicate

        :param key: query KEY parameter
        :param value: the value used in the predicate
        :param predicate_type: the type of predicate (e.g. ``equals``)
        """
        if predicate_type not in operators:
            predicate_type = operator_lkup.get(predicate_type)
        if predicate_type:
            self.predicates.append({'type': predicate_type,
                                    'key': key,
                                    'value': value
                                    })
        else:
            raise Exception("predicate type not a valid operator")

def step_mode(self, state_machine_id=None):
        """Set the execution mode to stepping mode. Transitions are only triggered if a new step is triggered
        """
        logger.debug("Activate step mode")

        if state_machine_id is not None:
            self.state_machine_manager.active_state_machine_id = state_machine_id

        self.run_to_states = []
        if self.finished_or_stopped():
            self.set_execution_mode(StateMachineExecutionStatus.STEP_MODE)
            self._run_active_state_machine()
        else:
            self.set_execution_mode(StateMachineExecutionStatus.STEP_MODE)

