def get_sensitivity(self, scalar=None):
        """True Positive Rate = TP / P = Num_True_Positive / (Num_True_Postive + Num_False_Negative)"""
        if scalar is None:
            return self.TP / (self.TP + self.FN)
        else:
            return self.TP / (self.TP + self.FN) * scalar

