def pop_context(self):
        """Pops the last set of keyword arguments provided to the processor."""
        processor = getattr(self, 'processor', None)
        if processor is not None:
            pop_context = getattr(processor, 'pop_context', None)
            if pop_context is None:
                pop_context = getattr(processor, 'pop', None)
            if pop_context is not None:
                return pop_context()
        if self._pop_next:
            self._pop_next = False

def pop_context(self):
        """Pops the last set of keyword arguments provided to the processor."""
        self.context.pop()

def getPluginVersion():
    """The version must be updated in the .cdmp file"""
    desc_file = os.path.join('cdmplugins', 'gc', plugin_desc_file)
    if not os.path.exists(desc_file):
        print('Cannot find the plugin description file. Expected here: ' +
              desc_file, file=sys.stderr)
        sys.exit(1)

    with open(desc_file) as dec_file:
        for line in dec_file:
            line = line.strip()
            if line.startswith('Version'):
                return line.split('=')[1].strip()
    print('Cannot find a version line in the ' + desc_file,
          file=sys.stderr)
    sys.exit(1)

def getPluginVersion():
    """The version must be updated in the .cdmp file"""
    return "1.0.0"

def string(num, length, digits=False, upper=True, lower=True, unique=False):
    """Random strings."""
    if digits:
        chars = '0123456789'
    else:
        chars = 'abcdefghijklmnopqrstuvwxyz'
    if upper:
        chars += 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if lower:
        chars += 'abcdefghijklmnopqrstuvwxyz'
    if unique:
        chars = list(set(chars))
    return ''.join([random.choice(chars) for _ in range(length)])

def getCandScoresMapBruteForce(self, profile):
        """
        Returns a dictonary that associates the integer representation of each candidate with the 
        bayesian losses that we calculate using brute force.

        :ivar Profile profile: A Profile object that represents an election profile.
        """
        candScoresMap = {}
        for cand in profile.candidates:
            candScoresMap[cand.id] = self.getCandScoreBruteForce(profile, cand)
        return candScoresMap

def _get_args(op, name):
    """Hack to get relevant arguments for lineage computation.

    We need a better way to determine the relevant arguments of an expression.
    """
    # Could use multipledispatch here to avoid the pasta
    if isinstance(op, ops.Selection):
        assert name is not None, 'name is None'
        result = op.selections

        # if Selection.selections is always columnar, could use an
        # OrderedDict to prevent scanning the whole thing
        return [col for col in result if col._name == name]
    elif isinstance(op, ops.Aggregation):
        assert name is not None, 'name is None'
        return [
            col
            for col in itertools.chain(op.by, op.metrics)
            if col._name == name
        ]
    else:
        return op.args

