def handle(self, message, connection):
        """ Delegate a received message to the appropriate handler.

        Args:
            message (Message) :
                The message that was receive that needs to be handled

            connection (ServerConnection) :
                The connection that received this message

        Raises:
            ProtocolError

        """
        if message.type == Message.TYPE_REQUEST:
            self.handle_request(message, connection)
        elif message.type == Message.TYPE_RESPONSE:
            self.handle_response(message, connection)
        elif message.type == Message.TYPE_EVENT:
            self.handle_event(message, connection)
        elif message.type == Message.TYPE_ERROR:
            self.handle_error(message, connection)
        else:
            raise ProtocolError('Invalid message type: %s' % message.type)

def to_networkx(cyjs, directed=True):
    """
    Convert Cytoscape.js-style JSON object into NetworkX object.

    By default, data will be handles as a directed graph.
    """
    import networkx as nx
    import json
    import uuid

    if not isinstance(cyjs, dict):
        raise ValueError("cyjs must be a dict")

    if not cyjs.get('elements'):
        raise ValueError("cyjs must contain elements")

    if not cyjs.get('elements').get('nodes'):
        raise ValueError("cyjs must contain nodes")

    if not cyjs.get('elements').get('edges'):
        raise ValueError("cyjs must contain edges")

    nodes = cyjs['elements']['nodes']
    edges = cyjs['elements']['edges']

    G = nx.MultiDiGraph() if directed else nx.MultiGraph()

    for node in nodes:
        if not node.get('data'):
            raise ValueError("node must contain data")

        if not node.get('data').get('id'):
            raise ValueError("node must contain id")

        if not node.get('data').get('label'):
            raise ValueError("node must contain label")

        G.add_node(node['data']['id'], label=node['data']['label'])

    for edge in edges:
        if not edge.get('data'):
            raise ValueError("edge must contain data")

        if not edge.get('data').get('id'):
            raise ValueError("edge must contain id")

        if not edge.get('data').get('source'):
            raise ValueError("edge must contain source")

        if not edge.get('data').get('target'):
            raise ValueError("edge must contain target")

        G.add_edge(edge['data']['source'], edge['data']['target'],
                   id=edge['data']['id'])

    return G

