def get_weight(self, rule):
        """Get weight for rule.

        If rule is not in :attr:`R`, returns ``None``.
        """
        if not issubclass(rule.__class__, (Rule, RuleLeaf)):
            raise TypeError("Rule to get weight ({}) is not subclass "
                            "of {} or {}.".format(rule, Rule, RuleLeaf))
        try:
            ind = self._R.index(rule)
            return self._W[ind]
        except:
            return None

def get_weight(self, rule):
        """Get weight for rule.

        If rule is not in :attr:`R`, returns ``None``.
        """
        return self.R.get(rule)

def get_riskmodel(taxonomy, oqparam, **extra):
    """
    Return an instance of the correct riskmodel class, depending on the
    attribute `calculation_mode` of the object `oqparam`.

    :param taxonomy:
        a taxonomy string
    :param oqparam:
        an object containing the parameters needed by the riskmodel class
    :param extra:
        extra parameters to pass to the riskmodel class
    """
    if oqparam.calculation_mode == 'deterministic':
        return DeterministicRiskModel(taxonomy, oqparam, **extra)
    elif oqparam.calculation_mode == 'stochastic':
        return StochasticRiskModel(taxonomy, oqparam, **extra)
    else:
        raise ValueError('Unknown calculation mode: {}'.format(
            oqparam.calculation_mode))

def as_view(self, view, cacheable=False, extra_permission=None):
        """
        Wraps a view in authentication/caching logic

        extra_permission can be used to require an extra permission for this view, such as a module permission
        """
        def inner(request, *args, **kwargs):
            if not self.has_permission(request, extra_permission):
                # show login pane
                return self.login(request)
            return view(request, *args, **kwargs)

        # Mark it as never_cache
        if not cacheable:
            inner = never_cache(inner)

        # We add csrf_protect here so this function can be used as a utility
        # function for any view, without having to repeat 'csrf_protect'.
        if not getattr(view, 'csrf_exempt', False):
            inner = csrf_protect(inner)

        inner = ensure_csrf_cookie(inner)

        return update_wrapper(inner, view)

