def extract_payload(self):
        """Extract payload from request."""
        if not self.check_signature():
            raise InvalidSignature('Invalid Signature')
        if request.is_json:
            # Request.get_json() could be first called with silent=True.
            delete_cached_json_for(request)
            return request.get_json(silent=False, cache=False)
        elif request.content_type == 'application/x-www-form-urlencoded':
            return dict(request.form)
        raise InvalidPayload(request.content_type)

def extract_payload(self):
        """Extract payload from request."""
        if self.request.content_type == 'application/json':
            return self.request.json
        elif self.request.content_type == 'application/x-www-form-urlencoded':
            return self.request.form
        else:
            return self.request.body

def sweep(self, mode, speed=None):
        """Starts the output current sweep.

        :param mode: The sweep mode. Valid entries are `'UP'`, `'DOWN'`,
            `'PAUSE'`or `'ZERO'`. If in shim mode, `'LIMIT'` is valid as well.
        :param speed: The sweeping speed. Valid entries are `'FAST'`, `'SLOW'`
            or `None`.

        """
        if speed is None:
            speed = self.speed
        if speed not in ['FAST', 'SLOW']:
            raise ValueError('Invalid speed.')
        if mode not in ['UP', 'DOWN', 'PAUSE', 'ZERO', 'LIMIT']:
            raise ValueError('Invalid mode.')
        if mode == 'UP':
            self.write('SWEEP UP')
        elif mode == 'DOWN':
            self.write('SWEEP DOWN')
        elif mode == 'PAUSE':
            self.write('SWEEP PAUSE')
        elif mode == 'ZERO':
            self.write('SWEEP ZERO')
        elif mode == 'LIMIT':
            self.write('SWEEP LIMIT')
        if speed == 'FAST':
            self.write('SPEED FAST')
        elif speed == 'SLOW':
            self.write('SPEED SLOW')

def _init_go_sources(self, go_sources_arg, go2obj_arg):
        """Return GO sources which are present in GODag."""
        go_sources = []
        go2obj = {}
        for go_source in go_sources_arg:
            if go_source in self:
                go_sources.append(go_source)
                go2obj[go_source] = self[go_source]
        if go2obj_arg is not None:
            go2obj.update(go2obj_arg)
        return go_sources, go2obj

def replace_if_changed(localfile, jottapath, JFS):
    """Compare md5 hash to determine if contents have changed.
    Upload a file from local disk and replace file on JottaCloud if the md5s differ,
    or continue uploading if the file is incompletely uploaded.

    Returns the JottaFile object"""
    jf = JFS.getObject(jottapath)
    lf_hash = getxattrhash(localfile) # try to read previous hash, stored in xattr
    if lf_hash is None:               # no valid hash found in xattr,
        with open(localfile) as lf:
            lf_hash = calculate_md5(lf) # (re)calculate it
    if type(jf) == JFSIncompleteFile:
        log.debug("Local file %s is incompletely uploaded, continue", localfile)
        return resume(localfile, jf, JFS)
    elif jf.md5 == lf_hash: # hashes are the same
        log.debug("hash match (%s), file contents haven't changed", lf_hash)
        setxattrhash(localfile, lf_hash)
        return jf         # return the version from jottaclouds
    else:
        setxattrhash(localfile, lf_hash)
        return new(localfile, jottapath, JFS)

def replace_if_changed(localfile, jottapath, JFS):
    """Compare md5 hash to determine if contents have changed.
    Upload a file from local disk and replace file on JottaCloud if the md5s differ,
    or continue uploading if the file is incompletely uploaded.

    Returns the JottaFile object"""
    # Get the md5 hash of the local file
    md5_local = hashlib.md5()
    with open(localfile, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            md5_local.update(chunk)

    # Get the md5 hash of the file on JottaCloud
    md5_jotta = JFS.get_file_md5(jottapath)

    # If the md5s differ, upload the file
    if md5_local.hexdigest() != md5_jotta:
        JFS.upload_file(localfile, jottapath)
        return JFS.get_file(jottapath)

    # If the md5s are the same, check if the file is complete
    elif md5_local.hexdigest() == md5_jotta:
        if JFS.get_file(jottapath).is_complete:
            return JFS.get_file(jottapath)
        else:
            JFS.upload_file(localfile, jottapath)
            return JFS.get_file(jottapath)

    else:
        print("Error: md5 hashes do not match")
        return None

def getenv(option, default=undefined, cast=undefined):
    """
    Return the value for option or default if defined.
    """

    # We can't avoid __contains__ because value may be empty.
    if option in os.environ:
        value = os.environ[option]
    else:
        if isinstance(default, Undefined):
            raise UndefinedValueError('{} not found. Declare it as envvar or define a default value.'.format(option))

        value = default

    if isinstance(cast, Undefined):
        return value

    if cast is bool:
        value = _cast_boolean(value)
    elif cast is list:
        value = [x for x in value.split(',') if x]
    else:
        value = cast(value)

    return value

def getenv(option, default=undefined, cast=undefined):
    """
    Return the value for option or default if defined.
    """
    if default is undefined:
        default = None
    if cast is undefined:
        cast = str
    return cast(os.getenv(option, default))

