def _febrl_links(df):
    """Get the links of a FEBRL dataset."""

    index = df.index.to_series()
    keys = index.str.extract(r'rec-(\d+)', expand=True)[0]

    index_int = numpy.arange(len(df))

    df_helper = pandas.DataFrame({
        'key': keys,
        'index': index_int
    })

    # merge the two frame and make MultiIndex.
    pairs_df = df_helper.merge(
        df_helper, on='key'
    )[['index_x', 'index_y']]
    pairs_df = pairs_df[pairs_df['index_x'] > pairs_df['index_y']]

    return pandas.MultiIndex(
        levels=[df.index.values, df.index.values],
        labels=[pairs_df['index_x'].values, pairs_df['index_y'].values],
        names=[None, None],
        verify_integrity=False
    )

def _febrl_links(df):
    """Get the links of a FEBRL dataset."""
    links = []
    for i in range(len(df)):
        links.append(f"https://www.febrl.com/data/data-sets/{df.iloc[i]['Dataset']}/{df.iloc[i]['Dataset']}.zip")
    return links

def parse_s2bins(s2bins):
    """
    parse ggKbase scaffold-to-bin mapping
        - scaffolds-to-bins and bins-to-scaffolds
    """
    s2b = {}
    b2s = {}
    for line in s2bins:
        line = line.strip().split()
        s, b = line[0], line[1]
        if 'UNK' in b:
            continue
        if len(line) > 2:
            g = ' '.join(line[2:])
        else:
            g = 'n/a'
        b = '%s\t%s' % (b, g)
        s2b[s] = b 
        if b not in b2s:
           b2s[b] = []
        b2s[b].append(s)
    return s2b, b2s

def parse_s2bins(s2bins):
    """
    parse ggKbase scaffold-to-bin mapping
        - scaffolds-to-bins and bins-to-scaffolds
    """
    scaffolds_to_bins = {}
    bins_to_scaffolds = {}
    with open(s2bins) as f:
        for line in f:
            line = line.strip().split()
            scaffold = line[0]
            bin_id = line[1]
            if scaffold not in scaffolds_to_bins:
                scaffolds_to_bins[scaffold] = []
            scaffolds_to_bins[scaffold].append(bin_id)
            if bin_id not in bins_to_scaffolds:
                bins_to_scaffolds[bin_id] = []
            bins_to_scaffolds[bin_id].append(scaffold)
    return scaffolds_to_bins, bins_to_scaffolds

