def _merge_meta(self, encoded_meta, meta):
        """
        Merge new meta dict into encoded meta. Returns new encoded meta.
        """
        new_meta = None

        if meta:
            _meta = self._decode_meta(encoded_meta)
            for key, value in six.iteritems(meta):
                if value is None:
                    _meta.pop(key, None)
                else:
                    _meta[key] = value
            new_meta = self._encode_meta(_meta)

        return new_meta

def _merge_meta(self, encoded_meta, meta):
        """
        Merge new meta dict into encoded meta. Returns new encoded meta.
        """
        if encoded_meta is None:
            encoded_meta = {}
        if meta is None:
            meta = {}
        for key, value in meta.items():
            if key in encoded_meta:
                if isinstance(encoded_meta[key], list):
                    encoded_meta[key].append(value)
                else:
                    encoded_meta[key] = [encoded_meta[key], value]
            else:
                encoded_meta[key] = value
        return encoded_meta

def upload_files_in_folder(self, dirname, fnames):
        """Handles the iteration across files within a folder."""
        if utils.match_pattern(dirname, self.ignore):
            return False
        good_names = (nm for nm in fnames
                if not utils.match_pattern(nm, self.ignore))
        for fname in good_names:
            if self.client._should_abort_folder_upload(self.upload_key):
                return
            full_path = os.path.join(dirname, fname)
            obj_name = os.path.relpath(full_path, self.root_folder)
            obj_size = os.stat(full_path).st_size
            self.client.upload_file(self.container, full_path,
                    obj_name=obj_name, return_none=True, ttl=self.ttl)
            self.client._update_progress(self.upload_key, obj_size)

def upload_files_in_folder(self, dirname, fnames):
        """Handles the iteration across files within a folder."""
        for fname in fnames:
            self.upload_file(os.path.join(dirname, fname))

