def set(self, child, min_occurs=1, max_occurs=1):
        """Set the schema for the sequence children.

        @param child: The schema that children must match.
        @param min_occurs: The minimum number of children the sequence
            must have.
        @param max_occurs: The maximum number of children the sequence
            can have.
        """
        if isinstance(child, LeafSchema):
            raise RuntimeError("Sequence can't have leaf children")
        if self.child is not None:
            raise RuntimeError("Sequence has already a child")
        if min_occurs is None or max_occurs is None:
            raise RuntimeError("Sequence node without min or max")
        if isinstance(child, LeafSchema):
            raise RuntimeError("Sequence node with leaf child type")
        if not child.tag == "item":
            raise RuntimeError("Sequence node with bad child tag")

        self.child = child
        self.min_occurs = min_occurs
        self.max_occurs = max_occurs
        return child

def set(self, child, min_occurs=1, max_occurs=1):
        """Set the schema for the sequence children.

        @param child: The schema that children must match.
        @param min_occurs: The minimum number of children the sequence
            must have.
        @param max_occurs: The maximum number of children the sequence
            can have.
        """
        self._children = child
        self._min_occurs = min_occurs
        self._max_occurs = max_occurs

def do_eval(self, args):
        """Eval the user-supplied statement. Note that you can do anything with
        this command that you can do in a template.

        The resulting value of your statement will be displayed.
        """
        try:
            res = self._interp.eval(args)
            if res is not None:
                if hasattr(res, "_pfp__show"):
                    print(res._pfp__show())
                else:
                    print(repr(res))
        except errors.UnresolvedID as e:
            print("ERROR: " + e.message)
        except Exception as e:
            raise
            print("ERROR: " + e.message)

        return False

def do_eval(self, args):
        """Eval the user-supplied statement. Note that you can do anything with
        this command that you can do in a template.

        The resulting value of your statement will be displayed.
        """
        try:
            result = self.eval(args)
        except Exception as e:
            result = e
        if isinstance(result, (list, tuple)):
            result = '\n'.join(result)
        print(result)

def _parse_subnet(self, subnet_dict):
        """Return the subnet, start, end, gateway of a subnet. """
        if not subnet_dict:
            return
        alloc_pool = subnet_dict.get('allocation_pools')
        cidr = subnet_dict.get('cidr')
        subnet = cidr.split('/')[0]
        start = alloc_pool[0].get('start')
        end = alloc_pool[0].get('end')
        gateway = subnet_dict.get('gateway_ip')
        sec_gateway = subnet_dict.get('secondary_gw')
        return {'subnet': subnet, 'start': start, 'end': end,
                'gateway': gateway, 'sec_gateway': sec_gateway}

