def copy_files(filelist, destdir):
    """Copy a list of files to destdir, preserving directory structure.

    File names should be relative to the current working directory.
    """
    for filename in filelist:
        destfile = os.path.join(destdir, filename)
        # filename should not be absolute, but let's double-check
        assert destfile.startswith(destdir + os.path.sep)
        destfiledir = os.path.dirname(destfile)
        if not os.path.isdir(destfiledir):
            os.makedirs(destfiledir)
        if os.path.isdir(filename):
            os.mkdir(destfile)
        else:
            shutil.copy2(filename, destfile)

def copy_files(filelist, destdir):
    """Copy a list of files to destdir, preserving directory structure.

    File names should be relative to the current working directory.
    """
    for f in filelist:
        dest = os.path.join(destdir, f)
        destdir = os.path.dirname(dest)
        if not os.path.exists(destdir):
            os.makedirs(destdir)
        shutil.copy(f, dest)

def line(h1: Histogram1D, **kwargs) -> dict:
    """Line plot of 1D histogram values.

    Points are horizontally placed in bin centers.

    Parameters
    ----------
    h1 : physt.histogram1d.Histogram1D
        Dimensionality of histogram for which it is applicable
    """

    lw = kwargs.pop("lw", DEFAULT_STROKE_WIDTH)

    mark_template = [{
        "type": "line",
        "encode": {
            "enter": {
                "x": {"scale": "xscale", "field": "x"},
                "y": {"scale": "yscale", "field": "y"},
                "stroke": {"scale": "series", "field": "c"},
                "strokeWidth": {"value": lw}
            }
        },
        "from": {"data": "series"},
    }]
    vega = _scatter_or_line(h1, mark_template=mark_template, kwargs=kwargs)
    return vega

def list_runners(*args):
    """
    List the runners loaded on the minion

    .. versionadded:: 2014.7.0

    CLI Example:

    .. code-block:: bash

        salt '*' sys.list_runners

    Runner names can be specified as globs.

    .. versionadded:: 2015.5.0

    .. code-block:: bash

        salt '*' sys.list_runners 'm*'

    """
    run_ = salt.runner.Runner(__opts__)
    runners = set()
    if not args:
        for func in run_.functions:
            runners.add(func.split('.')[0])
        return sorted(runners)

    for module in args:
        if '*' in module:
            for func in fnmatch.filter(run_.functions, module):
                runners.add(func.split('.')[0])
        else:
            for func in run_.functions:
                mod_test = func.split('.')[0]
                if mod_test == module:
                    runners.add(mod_test)
    return sorted(runners)

def trial(log_dir=None,
          upload_dir=None,
          sync_period=None,
          trial_prefix="",
          param_map=None,
          init_logging=True):
    """
    Generates a trial within a with context.
    """
    if param_map is None:
        param_map = {}

    if init_logging:
        init_logging_dir(log_dir)

    trial_id = generate_trial_id(trial_prefix)
    trial_dir = get_trial_dir(trial_id, log_dir)

    if upload_dir is not None:
        upload_dir = os.path.join(upload_dir, trial_id)
        if not os.path.exists(upload_dir):
            os.makedirs(upload_dir)

    if sync_period is not None:
        sync_period = int(sync_period)

    trial_params = {
        "trial_id": trial_id,
        "trial_dir": trial_dir,
        "upload_dir": upload_dir,
        "sync_period": sync_period,
        "param_map": param_map,
    }

    return trial_params

def get_account_by_ont_id(self, ont_id: str, password: str) -> Account:
        """
        :param ont_id: OntId.
        :param password: a password which is used to decrypt the encrypted private key.
        :return:
        """
        account = self.get_account_by_ont_id(ont_id)
        if account is None:
            raise ValueError("No account found for ont_id: {}".format(ont_id))
        if account.encrypted_private_key is None:
            raise ValueError("No encrypted private key found for ont_id: {}".format(ont_id))
        return self.decrypt_account(account, password)

def _create_index(self):
        """Create index if it doesn't exist."""
        if not self.index_exists:
            index_settings = {}
            headers = {'Content-Type': 'application/json', 'DB-Method': 'POST'}
            url = '/v2/exchange/db/{}/{}'.format(self.domain, self.data_type)
            r = self.tcex.session.post(url, json=index_settings, headers=headers)

            if not r.ok:
                error = r.text or r.reason
                self.tcex.handle_error(800, [r.status_code, error])
            self.tcex.log.debug(
                'creating index. status_code: {}, response: "{}".'.format(r.status_code, r.text)
            )

def _create_index(self):
        """Create index if it doesn't exist."""
        if not self.index_exists():
            self.create_index()

