def compute_writer_results(results):
    """Compute all the given dask graphs `results` so that the files are
    saved.

    Args:
        results (iterable): Iterable of dask graphs resulting from calls to
                            `scn.save_datasets(..., compute=False)`
    """
    if not results:
        return

    sources, targets, delayeds = split_results(results)

    # one or more writers have targets that we need to close in the future
    if targets:
        delayeds.append(da.store(sources, targets, compute=False))

    if delayeds:
        da.compute(delayeds)

    if targets:
        for target in targets:
            if hasattr(target, 'close'):
                target.close()

def _iter_list_for_dicts(self, check_list):
        """Iterate over list to find dicts and check for python keywords."""

        list_copy = copy.deepcopy(check_list)
        for index, elem in enumerate(check_list):
            if isinstance(elem, dict):
                list_copy[index] = self._check_for_python_keywords(elem)
            elif isinstance(elem, list):
                list_copy[index] = self._iter_list_for_dicts(elem)
            else:
                list_copy[index] = elem
        return list_copy

def _iter_list_for_dicts(self, check_list):
        """Iterate over list to find dicts and check for python keywords."""
        for item in check_list:
            if isinstance(item, dict):
                for key, value in item.items():
                    if key in self.python_keywords:
                        raise ValueError(
                            "Keyword {} is not allowed as key in a dict.".format(key)
                        )
                    if isinstance(value, list):
                        self._iter_list_for_dicts(value)

