def delete_invalid_route(self):
        """
        Delete any invalid routes for this interface. An invalid route is
        a left over when an interface is changed to a different network.

        :return: None
        """
        try:
            routing = self._engine.routing.get(self.interface_id)
            for route in routing:
                if route.invalid or route.to_delete:
                    route.delete()
        except InterfaceNotFound: # Only VLAN identifiers, so no routing
            pass

def split_vcf(in_file, ref_file, config, out_dir=None):
    """Split a VCF file into separate files by chromosome.
    """
    if out_dir is None:
        out_dir = os.path.dirname(in_file)
    out_file = os.path.join(out_dir, os.path.basename(in_file))
    if not out_file.endswith(".vcf"):
        out_file += ".vcf"
    if not os.path.exists(out_file):
        with file_transaction(config, out_file) as tx_out_file:
            with open(tx_out_file, "w") as out_handle:
                with open(in_file) as in_handle:
                    for line in in_handle:
                        if line.startswith("#"):
                            out_handle.write(line)
                        else:
                            chrom = line.split("\t")[0]
                            out_handle.write("##contig=<ID={0}>".format(chrom))
                            out_handle.write("\n")
                            out_handle.write(line)
    return out_file

def _format_value_error(self, v, e, pm=" +/- "):
        """
        Returns a string v +/- e with the right number of sig figs.
        """
        # If we have weird stuff
        if not _s.fun.is_a_number(v) or not _s.fun.is_a_number(e) \
            or v in [_n.inf, _n.nan, _n.NAN] or e in [_n.inf, _n.nan, _n.NAN]: 
            return str(v)+pm+str(e)

        # Normal values.
        try:
            sig_figs = -int(_n.floor(_n.log10(abs(e))))+1            
            return str(_n.round(v, sig_figs)) + pm + str(_n.round(e, sig_figs))

        except:
            return str(v)+pm+str(e)

def _format_value_error(self, v, e, pm=" +/- "):
        """
        Returns a string v +/- e with the right number of sig figs.
        """
        if e is None:
            return v
        else:
            return "{0:.{1}g} {2:.{1}g}".format(v, self.sigfigs, e)

def on_canvas_change(self, event):
        """Canvas change event handler

        Parameters
        ----------
        event : instance of Event
            The event.
        """
        if event.type == 'mouse_press':
            self.on_canvas_mouse_press(event)
        elif event.type == 'mouse_release':
            self.on_canvas_mouse_release(event)
        elif event.type == 'mouse_move':
            self.on_canvas_mouse_move(event)
        elif event.type == 'key_press':
            self.on_canvas_key_press(event)
        elif event.type == 'key_release':
            self.on_canvas_key_release(event)
        elif event.type == 'scroll':
            self.on_canvas_scroll(event)
        elif event.type == 'resize':
            self.on_canvas_resize(event)
        elif event.type == 'draw':
            self.on_canvas_draw(event)
        elif event.type == 'idle':
            self.on_canvas_idle(event)

def refresh(self, scope_list=None):
        """ Update the auth data (tokens) using the refresh token in auth.
        """
        if scope_list is None:
            scope_list = self.scope_list
        if self.refresh_token is None:
            raise ValueError("No refresh token available.")
        if self.auth_type == "oauth2":
            self.auth_data = self._refresh_oauth2(scope_list)
        elif self.auth_type == "oauth1":
            self.auth_data = self._refresh_oauth1(scope_list)
        else:
            raise ValueError("Unknown auth type: %s" % self.auth_type)
        self.save()

def list_platforms(server_url):
    """
    To list all ASAM platforms present on the Novell Fan-Out Driver

    CLI Example:

    .. code-block:: bash

        salt-run asam.list_platforms prov1.domain.com
    """
    config = _get_asam_configuration(server_url)
    if not config:
        return False

    url = config['platform_config_url']

    data = {
        'manual': 'false',
    }

    auth = (
        config['username'],
        config['password']
    )

    try:
        html_content = _make_post_request(url, data, auth, verify=False)
    except Exception as exc:
        err_msg = "Failed to look up existing platforms"
        log.error('%s:\n%s', err_msg, exc)
        return {server_url: err_msg}

    parser = _parse_html_content(html_content)
    platform_list = _get_platforms(parser.data)

    if platform_list:
        return {server_url: platform_list}
    else:
        return {server_url: "No existing platforms found"}

def _read_loop(self):
        """Read loop, splits by CRLF and pushes received data
        to _data.
        """
        while self._running:
            received_data_raw = self._receive_all()
            if self._running:
                self.receive_count += 1
                self.datetime_last_received = datetime.datetime.utcnow()
                received_data_split = received_data_raw.split(self.__CRLF)
                for received_data in received_data_split:
                    if received_data:
                        self._data(received_data)

def _read_loop(self):
        """Read loop, splits by CRLF and pushes received data
        to _data.
        """
        while self._running:
            try:
                data = self._sock.recv(self._bufsize)
                if not data:
                    break
                self._data.extend(data.splitlines(True))
            except socket.error as e:
                if e.args[0] == errno.EAGAIN:
                    pass
                else:
                    raise

def _GetFlowArgsHelpAsString(self, flow_cls):
    """Get a string description of the calling prototype for this flow."""
    output = [
        "  Call Spec:",
        "    %s" % self._GetCallingPrototypeAsString(flow_cls), ""
    ]
    arg_list = sorted(
        iteritems(self._GetArgsDescription(flow_cls.args_type)),
        key=lambda x: x[0])
    if not arg_list:
      output.append("  Args: None")
    else:
      output.append("  Args:")
      for arg, val in arg_list:
        output.append("    %s" % arg)
        output.append("      description: %s" % val["description"])
        output.append("      type: %s" % val["type"])
        output.append("      default: %s" % val["default"])
        output.append("")
    return "\n".join(output)

def close_others(self):
        """
        Closes every editors tabs except the current one.
        """
        current_widget = self.widget(self.tab_under_menu())
        if self._try_close_dirty_tabs(exept=current_widget):
            i = 0
            while self.count() > 1:
                widget = self.widget(i)
                if widget != current_widget:
                    self.remove_tab(i)
                else:
                    i = 1

