def get_variants_in_region(self, chrom, start, end):
        """Iterate over variants in a region."""
        region = self.get_vcf()(
            "{}:{}-{}".format(chrom, start, end)
        )
        for v in region:
            for coded_allele, g in self._make_genotypes(v.ALT, v.genotypes):
                variant = Variant(
                    v.ID, v.CHROM, v.POS, [v.REF, coded_allele]
                )
                yield Genotypes(variant, g, v.REF, coded_allele,
                                multiallelic=len(v.ALT) > 1)

def make_unique_script_attr(attributes):
    """
    Filter out duplicate `Script` TransactionAttributeUsage types.
    Args:
        attributes: a list of TransactionAttribute's

    Returns:
        list:
    """
    unique_attributes = []
    for attribute in attributes:
        if isinstance(attribute, TransactionAttribute):
            if attribute.usage != Script:
                unique_attributes.append(attribute)
            else:
                if attribute not in unique_attributes:
                    unique_attributes.append(attribute)
    return unique_attributes

