def lookup_object(model, object_id, slug, slug_field):
    """
    Return the ``model`` object with the passed ``object_id``.  If
    ``object_id`` is None, then return the object whose ``slug_field``
    equals the passed ``slug``.  If ``slug`` and ``slug_field`` are not passed,
    then raise Http404 exception.
    """
    lookup_kwargs = {}
    if object_id:
        lookup_kwargs['%s__exact' % model._meta.pk.name] = object_id
    elif slug and slug_field:
        lookup_kwargs['%s__exact' % slug_field] = slug
    else:
        raise GenericViewError(
            "Generic view must be called with either an object_id or a"
            " slug/slug_field.")
    try:
        return model.objects.get(**lookup_kwargs)
    except ObjectDoesNotExist:
        raise Http404("No %s found for %s"
                      % (model._meta.verbose_name, lookup_kwargs))

def lookup_object(model, object_id, slug, slug_field):
    """
    Return the ``model`` object with the passed ``object_id``.  If
    ``object_id`` is None, then return the object whose ``slug_field``
    equals the passed ``slug``.  If ``slug`` and ``slug_field`` are not passed,
    then raise Http404 exception.
    """
    if object_id:
        return get_object_or_404(model, pk=object_id)
    elif slug and slug_field:
        return get_object_or_404(model, **{slug_field: slug})
    else:
        raise Http404

def get_pub_str(self, name='master'):
        """
        Return the string representation of a public key
        in the pki-directory
        """
        path = os.path.join(self.opts['pki_dir'],
                            name + '.pub')
        if not os.path.isfile(path):
            key = self.__get_keys()
            if HAS_M2:
                key.save_pub_key(path)
            else:
                with salt.utils.files.fopen(path, 'wb+') as wfh:
                    wfh.write(key.publickey().exportKey('PEM'))
        with salt.utils.files.fopen(path) as rfh:
            return rfh.read()

def get_pub_str(self, name='master'):
        """
        Return the string representation of a public key
        in the pki-directory
        """
        return self._get_pub_str(name)

def lookup_language(languages, ranges):
    """
    Look up a single language in the sequence `languages` using the lookup
    mechansim described in RFC4647. If no match is found, :data:`None` is
    returned. Otherwise, the first matching language is returned.

    `languages` must be a sequence of :class:`LanguageTag` objects, while
    `ranges` must be an iterable of :class:`LanguageRange` objects.
    """

    for language_range in ranges:
        while True:
            try:
                return next(iter(basic_filter_languages(
                    languages,
                    [language_range])))
            except StopIteration:
                pass

            try:
                language_range = language_range.strip_rightmost()
            except ValueError:
                break

def lookup_language(languages, ranges):
    """
    Look up a single language in the sequence `languages` using the lookup
    mechansim described in RFC4647. If no match is found, :data:`None` is
    returned. Otherwise, the first matching language is returned.

    `languages` must be a sequence of :class:`LanguageTag` objects, while
    `ranges` must be an iterable of :class:`LanguageRange` objects.
    """
    for language in languages:
        for range in ranges:
            if range.match(language):
                return language
    return None

def update_all(self, criteria: Q, *args, **kwargs):
        """Update all objects satisfying the criteria """
        return self.update_many(criteria, *args, **kwargs)

def __verify_ready(self, creating=False):
        """Some cleanup, ensures that everything is set up properly to avoid
        random errors during execution

        Args:
            creating (bool): True if currently creating employer bees, False
                for checking all other operations
        """
        if creating:
            # If creating, check that the employer bee is ready
            if not self.employer_bee.is_ready():
                raise RuntimeError(
                    "Employer bee is not ready, cannot create employer bee"
                )
        else:
            # If not creating, check that the employer bee is ready
            if not self.employer_bee.is_ready():
                raise RuntimeError(
                    "Employer bee is not ready, cannot continue"
                )
            # Check that the bee is ready
            if not self.is_ready():
                raise RuntimeError(
                    "Bee is not ready, cannot continue"
                )

