def set_sparsemem(self, sparsemem):
        """
        Enable/disable use of sparse memory

        :param sparsemem: activate/deactivate sparsemem (boolean)
        """

        if sparsemem:
            flag = 1
        else:
            flag = 0
        yield from self._hypervisor.send('vm set_sparse_mem "{name}" {sparsemem}'.format(name=self._name, sparsemem=flag))

        if sparsemem:
            log.info('Router "{name}" [{id}]: sparse memory enabled'.format(name=self._name, id=self._id))
        else:
            log.info('Router "{name}" [{id}]: sparse memory disabled'.format(name=self._name, id=self._id))
        self._sparsemem = sparsemem

def mirror(self, handler, path_from, path_to, log_files=False):
        """Recursively mirror the contents of "path_from" into "path_to". 
        "handler" should be self.mirror_to_local_no_recursion or 
        self.mirror_to_remote_no_recursion to represent which way the files are
        moving.
        """
        if log_files:
            self.log_file_mirror(path_from, path_to)
        for item in self.list_dir(path_from):
            item_path_from = os.path.join(path_from, item)
            item_path_to = os.path.join(path_to, item)
            if self.is_dir(item_path_from):
                handler(item_path_from, item_path_to)
                self.mirror(handler, item_path_from, item_path_to, log_files)
            else:
                handler(item_path_from, item_path_to)

def list_parse(name_list):
    """Parse a comma-separated list of values, or a filename (starting with @)
    containing a list value on each line.
    """

    if name_list and name_list[0] == '@':
        value = name_list[1:]
        if not os.path.exists(value):
            log.warning('The file %s does not exist' % value)
            return
        try:
            return [v.strip() for v in open(value, 'r').readlines()]
        except IOError as e:
            log.warning('reading %s failed: %s; ignoring this file' %
                        (value, e))
    else:
        return [v.strip() for v in name_list.split(',')]

def list_parse(name_list):
    """Parse a comma-separated list of values, or a filename (starting with @)
    containing a list value on each line.
    """
    if name_list.startswith('@'):
        with open(name_list[1:], 'r') as f:
            return [line.strip() for line in f]
    else:
        return name_list.split(',')

def validate(self, value):
        """validate function form OrValidator

        Returns:
            True if at least one of the validators
            validate function return True
        """
        errors = []
        self._used_validator = []
        for val in self._validators:
            try:
                val.validate(value)
                self._used_validator.append(val)
            except ValidatorException as e:
                errors.append(e)
            except Exception as e:
                errors.append(ValidatorException("Unknown Error", e))
        if len(errors) > 0:
            raise ValidatorException.from_list(errors)
        return value

def validate(self, value):
        """validate function form OrValidator

        Returns:
            True if at least one of the validators
            validate function return True
        """
        for validator in self.validators:
            if validator.validate(value):
                return True
        return False

def _construct_X(self, omega, weighted=True, **kwargs):
        """Construct the design matrix for the problem"""
        t = kwargs.get('t', self.t)
        dy = kwargs.get('dy', self.dy)
        fit_offset = kwargs.get('fit_offset', self.fit_offset)

        if fit_offset:
            offsets = [np.ones(len(t))]
        else:
            offsets = []

        cols = sum(([np.sin((i + 1) * omega * t),
                     np.cos((i + 1) * omega * t)]
                    for i in range(self.Nterms)), offsets)

        if weighted:
            return np.transpose(np.vstack(cols) / dy)
        else:
            return np.transpose(np.vstack(cols))

def _construct_X(self, omega, weighted=True, **kwargs):
        """Construct the design matrix for the problem"""
        if self.X is None:
            if weighted:
                X = np.zeros((self.n, self.n))
                for i in range(self.n):
                    X[i, :] = np.exp(omega[i, :])
            else:
                X = np.eye(self.n)
            self.X = X
        return self.X

def build_funding(award_groups):
    """
    Given a funding data, format it
    """
    if not award_groups:
        return []

    funding_awards = []

    for award_groups_item in award_groups:
        for award_group_id, award_group in iteritems(award_groups_item):
            award = ea.FundingAward()
            award.award_group_id = award_group_id
            if award_group.get('id-type') == "FundRef":
                award.institution_id = award_group.get('id')

            award.institution_name = award_group.get('institution')

            # TODO !!! Check for multiple award_id, if exists
            if award_group.get('award-id'):
                award.add_award_id(award_group.get('award-id'))

            funding_awards.append(award)

    return funding_awards

