def validate_manifest_deployments(manifest: Dict[str, Any]) -> None:
    """
    Validate that a manifest's deployments contracts reference existing contract_types.
    """
    if set(("contract_types", "deployments")).issubset(manifest):
        all_contract_types = list(manifest["contract_types"].keys())
        all_deployments = list(manifest["deployments"].values())
        all_deployment_names = extract_contract_types_from_deployments(all_deployments)
        missing_contract_types = set(all_deployment_names).difference(
            all_contract_types
        )
        if missing_contract_types:
            raise ValidationError(
                f"Manifest missing references to contracts: {missing_contract_types}."
            )

def validate_manifest_deployments(manifest: Dict[str, Any]) -> None:
    """
    Validate that a manifest's deployments contracts reference existing contract_types.
    """
    for deployment in manifest["deployments"]:
        if deployment["contract_type"] not in manifest["contract_types"]:
            raise ValueError(
                f"Deployment '{deployment['name']}' references non-existing contract type '{deployment['contract_type']}'."
            )

def _get_ssl_version(self, value):
        """Get the TLS Version.

        :param str value:
        :return: TLS Version
        """
        if value == '1.0':
            return ssl.PROTOCOL_TLSv1
        elif value == '1.1':
            return ssl.PROTOCOL_TLSv1_1
        elif value == '1.2':
            return ssl.PROTOCOL_TLSv1_2
        elif value == '1.3':
            return ssl.PROTOCOL_TLSv1_3
        else:
            raise ValueError('Unsupported TLS Version: {}'.format(value))

def component_file_refs(filelist):
    """Get a list of what elements/refrences exist in component JSON files

    Parameters
    ----------
    filelist : list
        A list of paths to json files

    Returns
    -------
    dict
        Keys are the file path, value is a list of tuples (compacted element string, refs tuple)
    """

    ret = {}
    for fpath in filelist:
        filedata = fileio.read_json_basis(fpath)

        refdict = {}
        for el, eldata in filedata['elements'].items():
            refs = tuple(eldata['references'])
            if not refs in refdict:
                refdict[refs] = [el]
            else:
                refdict[refs].append(el)

        entry = []
        for k, v in refdict.items():
            entry.append((misc.compact_elements(v), k))

        ret[fpath] = entry

    return ret

def get(self, tags):
        """Find an adequate value for this field from a dict of tags."""
        if tags is None:
            return None
        if self.name in tags:
            return tags[self.name]
        if self.name in tags.get('properties', {}):
            return tags['properties'][self.name]
        return None

def _update_response_location_header(self, resource):
        """
        Adds a new or replaces an existing Location header to the response
        headers pointing to the URL of the given resource.
        """
        if resource.location is None:
            return
        if self.response.headers.get('Location') is None:
            self.response.headers['Location'] = resource.location
        else:
            self.response.headers['Location'] = resource.location

