                return self.bucket.get_object_info(key, user=user, chat=chat)
            else:
                return self.bucket.get_object_info(key, chat=chat)
        elif user is not None:
            return self.bucket.get_object_info(key, user=user)
        else:
            return self.bucket.get_object_info(key)

