async def type_cast_payload(schema: dict, payload: dict):
    """
    Make schema little forgiving! use case:  multipart data
    """
    # In ideal case this should be done using serializer. A temp measure right now
    cerberus_type_map = {
        'string': str,
        'integer': int,
        'float': float,
    }
    for field, validator in schema.items():
        field_type = validator['type']
        if field_type in ['integer', 'string', 'float']:
            payload_value = payload.get(field)
            if not payload_value:
                break
            try:
                payload[field] = cerberus_type_map[field_type](payload_value)
            except ValueError:
                break
    return payload

async def type_cast_payload(schema: dict, payload: dict):
    """
    Make schema little forgiving! use case:  multipart data
    """
    for key, value in schema.items():
        if isinstance(value, dict):
            payload[key] = type_cast_payload(value, payload[key])
        elif isinstance(value, list):
            payload[key] = [type_cast_payload(value[0], item) for item in payload[key]]
        else:
            try:
                payload[key] = value(payload[key])
            except:
                pass
    return payload

def write_error(self, status_code, **kwargs):
        """Write errors as JSON."""
        self.set_header("Content-Type", "application/json")
        if "exc_info" in kwargs:
            etype, exc, traceback = kwargs["exc_info"]
            if hasattr(exc, "messages"):
                self.write({"errors": exc.messages})
                if getattr(exc, "headers", None):
                    for name, val in exc.headers.items():
                        self.set_header(name, val)
                self.finish()

def wrap_file(file_like_obj):
    """Wrap a file like object in an async stream wrapper.

    Files generated with `open()` may be one of several types. This
    convenience function retruns the stream wrapped in the most appropriate
    wrapper for the type. If the stream is already wrapped it is returned
    unaltered.
    """
    if isinstance(file_like_obj, AsyncIOBaseWrapper):

        return file_like_obj

    if isinstance(file_like_obj, sync_io.FileIO):

        return AsyncFileIOWrapper(file_like_obj)

    if isinstance(file_like_obj, sync_io.BufferedRandom):

        return AsyncBufferedRandomWrapper(file_like_obj)

    if isinstance(file_like_obj, sync_io.BufferedReader):

        return AsyncBufferedReaderWrapper(file_like_obj)

    if isinstance(file_like_obj, sync_io.BufferedWriter):

        return AsyncBufferedWriterWrapper(file_like_obj)

    if isinstance(file_like_obj, sync_io.TextIOWrapper):

        return AsyncTextIOWrapperWrapper(file_like_obj)

    raise TypeError(
        'Unrecognized file stream type {}.'.format(file_like_obj.__class__),
    )

def wrap_file(file_like_obj):
    """Wrap a file like object in an async stream wrapper.

    Files generated with `open()` may be one of several types. This
    convenience function retruns the stream wrapped in the most appropriate
    wrapper for the type. If the stream is already wrapped it is returned
    unaltered.
    """
    if hasattr(file_like_obj, 'read'):
        if hasattr(file_like_obj, 'readinto'):
            return _AsyncFileWrapper(file_like_obj)
        elif hasattr(file_like_obj, 'readline'):
            return _AsyncTextIOWrapper(file_like_obj)
        else:
            return _AsyncFileWrapper(file_like_obj)
    else:
        return file_like_obj

def get_collectors(self, limit=1000, offset=0):
        """Returns a dict of collectors.

        Args:
            limit (int): number of collectors to return
            offset (int): the offset of where the list of collectors should begin from
        """
        options = {
            'limit': limit,
            'offset': offset,
        }
        request = requests.get(self.url, params=options, auth=self.auth)

        try:
            results = request.json()['collectors']
        except KeyError:
            results = request.json()
        except json.decoder.JSONDecodeError:
            results = []

        return results

