def get_identifier(self):
        """
        For methods this is the return type, the name and the (non-pretty)
        argument descriptor. For fields it is simply the name.

        The return-type of methods is attached to the identifier when
        it is a bridge method, which can technically allow two methods
        with the same name and argument type list, but with different
        return type.
        """
        if self.is_method():
            return '%s %s %s' % (self.return_type, self.name, self.descriptor)
        else:
            return self.name

def create_variable(descriptor):
    """
    Creates a variable from a dictionary descriptor
    """
    if descriptor['type'] == 'continuous':
        return ContinuousVariable(descriptor['name'], descriptor['domain'], descriptor.get('dimensionality', 1))
    elif descriptor['type'] == 'bandit':
        return BanditVariable(descriptor['name'], descriptor['domain'], descriptor.get('dimensionality', None))  # bandits variables cannot be repeated
    elif descriptor['type'] == 'discrete':
        return DiscreteVariable(descriptor['name'], descriptor['domain'], descriptor.get('dimensionality', 1))
    elif descriptor['type'] == 'categorical':
        return CategoricalVariable(descriptor['name'], descriptor['domain'], descriptor.get('dimensionality', 1))
    else:
        raise InvalidConfigError('Unknown variable type ' + descriptor['type'])

def create_variable(descriptor):
    """
    Creates a variable from a dictionary descriptor
    """
    if descriptor['type'] == 'int':
        return int(descriptor['value'])
    elif descriptor['type'] == 'float':
        return float(descriptor['value'])
    elif descriptor['type'] == 'string':
        return descriptor['value']
    elif descriptor['type'] == 'boolean':
        return descriptor['value']
    elif descriptor['type'] == 'list':
        return [create_variable(item) for item in descriptor['value']]
    elif descriptor['type'] == 'dict':
        return {key: create_variable(value) for key, value in descriptor['value'].items()}
    else:
        raise Exception('Unknown variable type')

def any2sql(func, definition_dict=None, **definition_kwargs):
    """Handle general to SQL conversion.

    :param func: function to be called on the given definition
    :param definition_dict: statement definition in dict
    :param definition_kwargs: statement definition as kwargs
    :return: raw SQL statement
    """
    if definition_dict and definition_kwargs:
        raise InputError("Cannot process dict and kwargs input at the same time")

    definition = load_input(definition_dict or definition_kwargs)

    if definition.get('returning', '') == '*':
        definition['returning'] = mosql_raw('*')

    try:
        result = func(**definition)
    except (TypeError, AttributeError) as exc:
        raise ClauseError("Clause definition error: %s" % str(exc)) from exc
    except Exception as exc:
        import json2sql.errors as json2sql_errors

        if exc.__class__.__name__ not in json2sql_errors.__dict__.keys():
            raise json2sql_errors.Json2SqlInternalError("Unhandled error: %s" % str(exc)) from exc
        raise

    return result

def any2sql(func, definition_dict=None, **definition_kwargs):
    """Handle general to SQL conversion.

    :param func: function to be called on the given definition
    :param definition_dict: statement definition in dict
    :param definition_kwargs: statement definition as kwargs
    :return: raw SQL statement
    """
    if definition_dict is None:
        definition_dict = {}
    definition_dict.update(definition_kwargs)
    return func(**definition_dict)

def team_id(self,team):
        """
        Get team ID using a real team name
        @return: id
        """
        #UTF-8 comparison
        headers = {"Content-type": "application/x-www-form-urlencoded","Accept": "text/plain",'Referer': 'http://'+self.domain+'/',"User-Agent": user_agent}
        req = self.session.get('http://'+self.domain,headers=headers).content
        soup = BeautifulSoup(req)
        for i in soup.find('table',cellpadding=2).find_all('tr'):
            #Get teamid from the bets
            team1 = i.find('a')['title']
            team2 = i.find_all('a')[1]['title']
            if (team == team1):
                return i.find('a')['href'].split('cid=')[1]
            elif (team == team2):
                return i.find_all('a')[1]['href'].split('cid=')[1]
        return None

