def assign_fonts(counts,maxsize,minsize,exclude_words):
    """Defines the font size of a word in the cloud.
    Counts is a list of tuples in the form (word,count)"""
    valid_counts = []
    if exclude_words:
        for i in counts:
            if i[1] != 1:
                valid_counts.append(i)
    else:
        valid_counts = counts
    frequencies = map(lambda x: x[1],valid_counts)
    words = map(lambda x: x[0],valid_counts)
    maxcount = max(frequencies)
    font_sizes = map(lambda x:fontsize(x,maxsize,minsize,maxcount),frequencies)
    size_dict = dict(zip(words, font_sizes))
    return size_dict

def assign_fonts(counts,maxsize,minsize,exclude_words):
    """Defines the font size of a word in the cloud.
    Counts is a list of tuples in the form (word,count)"""
    font_sizes = []
    for word,count in counts:
        if word in exclude_words:
            font_sizes.append(0)
        else:
            font_sizes.append(maxsize*count/max(counts,key=lambda x:x[1])[1])
    return font_sizes

def add_infos(self, *keyvals, **kwargs):
    """Adds the given info and returns a dict composed of just this added info."""
    kv_pairs = []
    for key, val in keyvals:
      key = key.strip()
      val = str(val).strip()
      if ':' in key:
        raise ValueError('info key "{}" must not contain a colon.'.format(key))
      kv_pairs.append((key, val))

    for k, v in kv_pairs:
      if k in self._info:
        raise ValueError('info key "{}" already exists with value {}. '
                         'Cannot add it again with value {}.'.format(k, self._info[k], v))
      self._info[k] = v

    try:
      with open(self._info_file, 'a') as outfile:
        for k, v in kv_pairs:
          outfile.write('{}: {}\n'.format(k, v))
    except IOError:
      if not kwargs.get('ignore_errors', False):
        raise

def add_infos(self, *keyvals, **kwargs):
    """Adds the given info and returns a dict composed of just this added info."""
    for key, val in keyvals:
      self._infos[key].append(val)
    for key, val in kwargs.items():
      self._infos[key].append(val)
    return self._infos

def queue(self, queue, message, params={}, uids=[]):
        """
        Queue a job in Rhumba
        """

        d = {
            'id': uuid.uuid1().get_hex(),
            'version': 1,
            'message': message,
            'params': params
        }

        ser = json.dumps(d)

        if uids:
            for uid in uids:
                path = '/dq/%s/%s' % (uid, queue)
                yield self._put_queue(path, ser)

        else:
            path = '/q/%s' % queue
            yield self._put_queue(path, ser)

        defer.returnValue(d['id'])

def queue(self, queue, message, params={}, uids=[]):
        """
        Queue a job in Rhumba
        """
        if not isinstance(queue, str):
            raise TypeError("queue must be a string")
        if not isinstance(message, str):
            raise TypeError("message must be a string")
        if not isinstance(params, dict):
            raise TypeError("params must be a dictionary")
        if not isinstance(uids, list):
            raise TypeError("uids must be a list")

        if not uids:
            uids = self.get_uids()

        for uid in uids:
            self.send_message(
                uid,
                message,
                params={
                    "queue": queue,
                    "message": message,
                    "params": params,
                },
            )

def set_password(self, service, username, password):
        """Write the password in the file.
        """
        if not self.is_valid_service(service):
            raise ValueError('Invalid service')
        if not self.is_valid_username(username):
            raise ValueError('Invalid username')
        if not self.is_valid_password(password):
            raise ValueError('Invalid password')

        self.passwords[service][username] = password

def parse(self, parser, xml):
        """Parses the rawtext to extract contents and references."""
        #We can only process references if the XML tag has inner-XML
        if xml.text is not None:
            matches = parser.RE_REFS.finditer(xml.text)
            if matches:
                for match in matches:
                    #Handle "special" references to this.name and param.name here.
                    self.references.append(match.group("reference"))

        #We also need to get all the XML attributes into the element
        for key in list(xml.keys()):
            self.attributes[key] = xml.get(key)

def parse_limits_file(path):
    """Parse a file as a list of reaction flux limits

    The file format is detected and the file is parsed accordingly. Path can
    be given as a string or a context.
    """
    if isinstance(path, str):
        with open(path, "r") as f:
            return parse_limits_file(f)
    elif isinstance(path, io.TextIOWrapper):
        return parse_limits_file(path.readlines())
    elif isinstance(path, list):
        return parse_limits_file(path)
    else:
        raise TypeError("path must be a string, a file-like object, or a list")

def download(url, target_file, chunk_size=4096):
    """
    Simple requests downloader
    """
    r = requests.get(url, stream=True)
    with open(target_file, 'wb') as f:
        for chunk in r.iter_content(chunk_size=chunk_size):
            if chunk:
                f.write(chunk)

def build_current_graph():
    """
    Read current state of SQL items from the current project state.

    Returns:
        (SQLStateGraph) Current project state graph.
    """
    graph = SQLStateGraph()
    for app_name, config in apps.app_configs.items():
        try:
            module = import_module(
                '.'.join((config.module.__name__, SQL_CONFIG_MODULE)))
            sql_items = module.sql_items
        except (ImportError, AttributeError):
            continue
        for sql_item in sql_items:
            graph.add_node((app_name, sql_item.name), sql_item)

            for dep in sql_item.dependencies:
                graph.add_lazy_dependency((app_name, sql_item.name), dep)

    graph.build_graph()
    return graph

def get_jids():
    """
    List all the jobs that we have..
    """
    options = _get_options(ret=None)
    _response = _request("GET", options['url'] + options['db'] + "/_all_docs?include_docs=true")

    # Make sure the 'total_rows' is returned.. if not error out.
    if 'total_rows' not in _response:
        log.error('Didn\'t get valid response from requesting all docs: %s', _response)
        return {}

    # Return the rows.
    ret = {}
    for row in _response['rows']:
        # Because this shows all the documents in the database, including the
        # design documents, verify the id is salt jid
        jid = row['id']
        if not salt.utils.jid.is_jid(jid):
            continue

        ret[jid] = salt.utils.jid.format_jid_instance(jid, row['doc'])

    return ret

def _register_task(self, output_type, rule, union_rules):
    """Register the given TaskRule with the native scheduler."""
    func = Function(self._to_key(rule.func))
    self._native.lib.tasks_task_begin(self._tasks, func, self._to_type(output_type), rule.cacheable)
    for selector in rule.input_selectors:
      self._native.lib.tasks_add_select(self._tasks, self._to_type(selector))

    def add_get_edge(product, subject):
      self._native.lib.tasks_add_get(self._tasks, self._to_type(product), self._to_type(subject))

    for the_get in rule.input_gets:
      union_members = union_rules.get(the_get.subject_declared_type, None)
      if union_members:
        # If the registered subject type is a union, add Get edges to all registered union members.
        for union_member in union_members:
          add_get_edge(the_get.product, union_member)
      else:
        # Otherwise, the Get subject is a "concrete" type, so add a single Get edge.
        add_get_edge(the_get.product, the_get.subject_declared_type)

    self._native.lib.tasks_task_end(self._tasks)

def _register_task(self, output_type, rule, union_rules):
    """Register the given TaskRule with the native scheduler."""
    if output_type not in self._task_rules:
      self._task_rules[output_type] = []
    self._task_rules[output_type].append(rule)
    self._union_rules[output_type] = union_rules

def arrays2wcxf(C):
    """Convert a dictionary with Wilson coefficient names as keys and
    numbers or numpy arrays as values to a dictionary with a Wilson coefficient
    name followed by underscore and numeric indices as keys and numbers as
    values. This is needed for the output in WCxf format."""
    d = {}
    for k, v in C.items():
        if np.shape(v) == () or np.shape(v) == (1,):
            d[k] = v
        else:
            ind = np.indices(v.shape).reshape(v.ndim, v.size).T
            for i in ind:
                name = k + '_' + ''.join([str(int(j) + 1) for j in i])
                d[name] = v[tuple(i)]
    return d

def arrays2wcxf(C):
    """Convert a dictionary with Wilson coefficient names as keys and
    numbers or numpy arrays as values to a dictionary with a Wilson coefficient
    name followed by underscore and numeric indices as keys and numbers as
    values. This is needed for the output in WCxf format."""
    C_wcxf = {}
    for key in C:
        if isinstance(C[key], (int, float)):
            C_wcxf[key] = C[key]
        else:
            for i in range(C[key].shape[0]):
                C_wcxf[key + '_' + str(i)] = C[key][i]
    return C_wcxf

def __notify(self):
        """
        Notify the given callback about the result of the execution
        """
        if self.__callback is not None:
            try:
                self.__callback(
                    self._done_event.data,
                    self._done_event.exception,
                    self.__extra,
                )
            except Exception as ex:
                self._logger.exception("Error calling back method: %s", ex)

def __notify(self):
        """
        Notify the given callback about the result of the execution
        """
        if self.callback:
            self.callback(self.result)

def next_packet(self):
        """
        Process next packet if present
        """
        try:
            start_byte_index = self.buffer.index(velbus.START_BYTE)
        except ValueError:
            self.buffer = bytes([])
            return
        if start_byte_index >= 0:
            self.buffer = self.buffer[start_byte_index:]
        if self.valid_header_waiting() and self.valid_body_waiting():
            next_packet = self.extract_packet()
            self.buffer = self.buffer[len(next_packet):]
            message = self.parse(next_packet)
            if isinstance(message, velbus.Message):
                self.controller.new_message(message)

def next_packet(self):
        """
        Process next packet if present
        """
        if self.packet_queue.empty():
            return None
        return self.packet_queue.get()

