        self.integridad_data()

def load_data(self, key=None, **kwargs):
        """ Lee de disco la información y la devuelve
        :param key:
        """
        if key is None:
            key = self.key
        if key is None:
            raise ValueError("No se ha especificado el key")
        if key not in self.data:
            self.data[key] = self.load(key, **kwargs)
        return self.data[key]

def from_json(cls, data):
        """Create a Humidity Condition from a dictionary.

        Args:
            data = {
            "hum_type": string,
            "hum_value": float,
            "barometric_pressure": float,
            "schedule": string,
            "wet_bulb_range": string}
        """
        # Check required and optional keys
        required_keys = ('hum_type', 'hum_value')
        optional_keys = {'barometric_pressure': 101325,
                         'schedule': '', 'wet_bulb_range': ''}
        for key in required_keys:
            assert key in data, 'Required key "{}" is missing!'.format(key)
        for key, val in optional_keys.items():
            if key not in data:
                data[key] = val

        return cls(data['hum_type'], data['hum_value'], data['barometric_pressure'],
                   data['schedule'], data['wet_bulb_range'])

def get_status(self, response, finished=False):
        """Given the stdout from the command returned by :meth:`cmd_status`,
        return one of the status code defined in :mod:`clusterjob.status`"""
        status_pos = 0
        for line in response.split("\n"):
            if line.startswith('JOBID'):
                try:
                    status_pos = line.find('STAT')
                except ValueError:
                    return None
            else:
                status = line[status_pos:].split()[0]
                if status in self.status_mapping:
                    return self.status_mapping[status]
        return None

def get_status(self, response, finished=False):
        """Given the stdout from the command returned by :meth:`cmd_status`,
        return one of the status code defined in :mod:`clusterjob.status`"""
        if finished:
            return status.FINISHED
        if response.startswith('PENDING'):
            return status.PENDING
        if response.startswith('RUNNING'):
            return status.RUNNING
        if response.startswith('CANCELLED'):
            return status.CANCELLED
        if response.startswith('FAILED'):
            return status.FAILED
        if response.startswith('TIMEOUT'):
            return status.TIMEOUT
        if response.startswith('UNKNOWN'):
            return status.UNKNOWN
        if response.startswith('REQUEUED'):
            return status.REQUEUED
        if response.startswith('RESTARTED'):
            return status.RESTARTED
        if response.startswith('REVOKED'):
            return status.REVOKED
        if response.startswith('REMOVED'):
            return status.REMOVED
        if response.startswith('SUSPENDED'):
            return status.SUSPENDED
        if response.startswith('RESUMED'):
            return status.RESUMED
        if response.startswith('RESTARTING'):
            return status.RESTARTING
        if response.startswith('RESIZING'):
            return status.RESIZING
        if response.startswith('RESIZED'):
            return status.RESIZED
        if response.startswith('PREEMPTED'):
            return status.PREEMPTED
        if response.startswith('SPECIAL_EXIT'):
            return status.SPECIAL_EXIT
        if response.startswith('BOOT_FAIL'):
            return status.BOOT_FAIL
        if response.startswith('DELETED'):
            return status.DELETED
        if response.startswith('NODE_FAIL'):
            return status.NODE_FAIL
        if response.startswith('OUT_OF_MEMORY'):
            return status.OUT_OF_MEMORY
        if response.startswith('PREEMPTED_SUSPENDED'):
            return status

def cget(self, key):
        """
        Query widget option.

        :param key: option name
        :type key: str
        :return: value of the option

        To get the list of options for this widget, call the method :meth:`~ScaleEntry.keys`.
        """
        if key == 'scalewidth':
            return self._scale.cget('length')
        elif key == 'from':
            return self._scale.cget('from')
        elif key == 'to':
            return self._scale.cget('to')
        elif key == 'entrywidth':
            return self._entry.cget('width')
        elif key == 'entryscalepad':
            return self.__entryscalepad
        elif key == 'compound':
            return self.__compound
        elif key == 'orient':
            return str(self._scale.cget('orient'))
        else:
            return ttk.Frame.cget(self, key)

