def _handle_ignores(testtag):
    """Checks if the specified test tag has attribute "ignores"; if it
    does, a <global ignore="true" /> tag is created for each variable
    name in the list.
    """
    if testtag.getAttribute("ignores"):
        for ignore in testtag.getAttribute("ignores").split(","):
            ignore = ignore.strip()
            if ignore:
                ignore = "<global ignore=\"%s\" />" % ignore
                testtag.insert(0, ignore)
